1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/peripherals/wbdmac.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	Wishbone DMA controller
8	//
9	//	This module is controllable via the wishbone, and moves values from
10	//	one location in the wishbone address space to another.  The amount of
11	//	memory moved at any given time can be up to 4kB, or equivalently 1kW.
12	//	Four registers control this DMA controller: a control/status register,
13	//	a length register, a source WB address and a destination WB address.
14	//	These register may be read at any time, but they may only be written
15	//	to when the controller is idle.
16	//
17	//	The meanings of three of the setup registers should be self explanatory:
18	//		- The length register controls the total number of words to
19	//			transfer.
20	//		- The source address register controls where the DMA controller
21	//			reads from.  This address may or may not be incremented
22	//			after each read, depending upon the setting in the
23	//			control/status register.
24	//		- The destination address register, which controls where the DMA
25	//			controller writes to.  This address may or may not be
26	//			incremented after each write, also depending upon the
27	//			setting in the control/status register.
28	//
29	//	It is the control/status register, at local address zero, that needs
30	//	more definition:
31	//
32	//	Bits:
33	//	31	R	Write protect	If this is set to one, it means the
34	//				write protect bit is set and the controller
35	//				is therefore idle.  This bit will be set upon
36	//				completing any transfer.
37	//	30	R	Error.		The controller stopped mid-transfer
38	//					after receiving a bus error.
39	//	29	R/W	inc_s_n		If set to one, the source address
40	//				will not increment from one read to the next.
41	//	28	R/W	inc_d_n		If set to one, the destination address
42	//				will not increment from one write to the next.
43	//	27	R	Always 0
44	//	26..16	R	nread		Indicates how many words have been read,
45	//				and not necessarily written (yet).  This
46	//				combined with the cfg_len parameter should tell
47	//				exactly where the controller is at mid-transfer.
48	//	27..16	W	WriteProtect	When a 12'h3db is written to these
49	//				bits, the write protect bit will be cleared.
50	//
51	//	15	R/W	on_dev_trigger	When set to '1', the controller will
52	//				wait for an external interrupt before starting.
53	//	14..10	R/W	device_id	This determines which external interrupt
54	//				will trigger a transfer.
55	//	9..0	R/W	transfer_len	How many bytes to transfer at one time.
56	//				The minimum transfer length is one, while zero
57	//				is mapped to a transfer length of 1kW.
58	//
59	//	Write 32'hffed00 to halt an ongoing transaction, completing anything
60	//	remaining, or 32'hafed00 to abort the current transaction leaving
61	//	any unfinished read/write in an undetermined state.
62	//
63	//
64	//	To use this, follow this checklist:
65	//	1. Wait for any prior DMA operation to complete
66	//		(Read address 0, wait 'till either top bit is set or cfg_len==0)
67	//	2. Write values into length, source and destination address.
68	//		(writei(3, &vals) should be sufficient for this.)
69	//	3. Enable the DMAC interrupt in whatever interrupt controller is present
70	//		on the system.
71	//	4. Write the final start command to the setup/control/status register:
72	//		Set inc_s_n, inc_d_n, on_dev_trigger, dev_trigger,
73	//			appropriately for your task
74	//		Write 12'h3db to the upper word.
75	//		Set the lower word to either all zeros, or a smaller transfer
76	//		length if desired.
77	//	5. wait() for the interrupt and the operation to complete.
78	//		Prior to completion, number of items successfully transferred
79	//		be read from the length register.  If the internal buffer is
80	//		being used, then you can read how much has been read into that
81	//		buffer by reading from bits 25..16 of this control/status
82	//		register.
83	//
84	// Creator:	Dan Gisselquist, Ph.D.
85	//		Gisselquist Technology, LLC
86	//
87	////////////////////////////////////////////////////////////////////////////////
88	// }}}
89	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
90	// {{{
91	// This program is free software (firmware): you can redistribute it and/or
92	// modify it under the terms of the GNU General Public License as published
93	// by the Free Software Foundation, either version 3 of the License, or (at
94	// your option) any later version.
95	//
96	// This program is distributed in the hope that it will be useful, but WITHOUT
97	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
98	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
99	// for more details.
100	//
101	// You should have received a copy of the GNU General Public License along
102	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
103	// target there if the PDF file isn't present.)  If not, see
104	// <http://www.gnu.org/licenses/> for a copy.
105	// }}}
106	// License:	GPL, v3, as defined and found on www.gnu.org,
107	// {{{
108	//		http://www.gnu.org/licenses/gpl.html
109	//
110	////////////////////////////////////////////////////////////////////////////////
111	//
112	`default_nettype none
113	// }}}
114	module wbdmac #(
115			// {{{
116			parameter	ADDRESS_WIDTH=30, LGMEMLEN = 10,
117			parameter	SLV_WIDTH=32,
118			parameter	BUS_WIDTH=32,
119			localparam	AW=ADDRESS_WIDTH
120			// }}}
121		) (
122			// {{{
123			input	wire		i_clk, i_reset,
124			// Slave port
125			// {{{
126			// Slave/control wishbone inputs
127			input	wire		i_swb_cyc, i_swb_stb, i_swb_we,
128			input	wire	[1:0]	i_swb_addr,
129			input	wire [(SLV_WIDTH-1):0]	i_swb_data,
130			// Slave/control wishbone outputs
131			output	wire		o_swb_stall,
132			output	reg		o_swb_ack,
133			output	reg [(SLV_WIDTH-1):0]	o_swb_data,
134			// }}}
135			// Master/DMA port
136			// {{{
137			output	wire			o_mwb_cyc, o_mwb_stb, o_mwb_we,
138			output	reg [(AW-1):0]		o_mwb_addr,
139			output	reg [(BUS_WIDTH-1):0]	o_mwb_data,
140			// Master/DMA wishbone responses from the bus
141			input	wire			i_mwb_stall, i_mwb_ack,
142			input	wire [(BUS_WIDTH-1):0]	i_mwb_data,
143			input	wire			i_mwb_err,
144			// }}}
145			// The interrupt device interrupt lines
146			input	wire [31:0]		i_dev_ints,
147			// An interrupt to be set upon completion
148			output	reg			o_interrupt
149			// }}}
150		);
151	
152		// Local declarations
153		// {{{
154		localparam	LGDV=5;
155		localparam [2:0]	DMA_IDLE	= 3'b000,
156					DMA_WAIT	= 3'b001,
157					DMA_READ_REQ	= 3'b010,
158					DMA_READ_ACK	= 3'b011,
159					DMA_PRE_WRITE	= 3'b100,
160					DMA_WRITE_REQ	= 3'b101,
161					DMA_WRITE_ACK	= 3'b110;
162	
163		wire			s_cyc, s_stb, s_we;
164		wire	[1:0]		s_addr;
165		wire	[SLV_WIDTH-1:0]	s_data;
166	
167		reg	[2:0]		dma_state;
168		reg			cfg_err, cfg_len_nonzero;
169		reg	[(AW-1):0]	cfg_waddr, cfg_raddr, cfg_len;
170		reg [(LGMEMLEN-1):0]	cfg_blocklen_sub_one;
171		reg			cfg_incs, cfg_incd;
172		reg	[(LGDV-1):0]	cfg_dev_trigger;
173		reg			cfg_on_dev_trigger;
174	
175		// Single block operations: We'll read, then write, up to a single
176		// memory block here.
177	
178		reg	[BUS_WIDTH-1:0]	dma_mem	[0:(((1<<LGMEMLEN))-1)];
179		reg	[(LGMEMLEN):0]	nread, nwritten, nwacks, nracks;
180		wire	[(AW-1):0]	bus_nracks;
181	
182		reg	last_read_request, last_read_ack,
183			last_write_request, last_write_ack;
184		reg	trigger, abort, user_halt;
185	
186		wire	[(LGMEMLEN):0]	next_nread;
187		reg	[(LGMEMLEN-1):0]	rdaddr;
188		// }}}
189	
190		localparam [0:0]	OPT_DELAY_BUS_ACCESS = 1;
191	
192		generate if (OPT_DELAY_BUS_ACCESS)
193		begin : DELAY_ACCESS
194			// {{{
195			reg	r_s_cyc, r_s_stb, r_s_we;
196			reg	[1:0]	r_s_addr;
197			reg	[SLV_WIDTH-1:0]	r_s_data;
198	
199			always @(posedge i_clk)
200				r_s_cyc <= i_swb_cyc;
201	
202			always @(posedge i_clk)
203			if (i_reset)
204				r_s_stb <= 1'b0;
205			else
206				r_s_stb <= i_swb_stb;
207	
208			always @(posedge i_clk)
209				r_s_we  <= i_swb_we;
210			always @(posedge i_clk)
211				r_s_addr<= i_swb_addr;
212			always @(posedge i_clk)
213				r_s_data<= i_swb_data;
214	
215			assign	s_cyc = r_s_cyc;
216			assign	s_stb = r_s_stb;
217			assign	s_we  = r_s_we;
218			assign	s_addr= r_s_addr;
219			assign	s_data= r_s_data;
220			// }}}
221		end else begin : STRAIGHT_SLAVE_ACCESS
222			// {{{
223			assign	s_cyc = i_swb_cyc;
224			assign	s_stb = i_swb_stb;
225			assign	s_we  = i_swb_we;
226			assign	s_addr= i_swb_addr;
227			assign	s_data= i_swb_data;
228			// }}}
229		end endgenerate
230	
231		assign	bus_nracks = { {(AW-LGMEMLEN-1){1'b0}}, nracks };
232	
233		// Monster state machine
234		// {{{
235		initial	dma_state = DMA_IDLE;
236		initial	o_interrupt = 1'b0;
237		initial	cfg_blocklen_sub_one = {(LGMEMLEN){1'b1}};
238		initial	cfg_on_dev_trigger = 1'b0;
239		always @(posedge i_clk)
240		if (i_reset)
241		begin
242			// {{{
243			dma_state <= DMA_IDLE;
244			cfg_on_dev_trigger <= 1'b0;
245			cfg_incs  <= 1'b0;
246			cfg_incd  <= 1'b0;
247			// }}}
248		end else case(dma_state)
249		DMA_IDLE: begin
250			// {{{
251			o_mwb_addr <= cfg_raddr;
252	
253			// When the slave wishbone writes, and we are in this
254			// (ready) configuration, then allow the DMA to be controlled
255			// and thus to start.
256			if ((s_stb)&&(s_we))
257			begin
258				case(s_addr)
259				2'b00: begin
260					if ((s_data[27:16] == 12'hfed)
261						&&(s_data[31:30] == 2'b00)
262							&&(cfg_len_nonzero))
263						dma_state <= DMA_WAIT;
264					cfg_blocklen_sub_one
265						<= s_data[(LGMEMLEN-1):0]
266						+ {(LGMEMLEN){1'b1}};
267						// i.e. -1;
268					cfg_dev_trigger    <= s_data[14:10];
269					cfg_on_dev_trigger <= s_data[15];
270					cfg_incs  <= !s_data[29];
271					cfg_incd  <= !s_data[28];
272					end
273				2'b01: begin end // This is done elsewhere
274				2'b10: cfg_raddr <=  s_data[$clog2(BUS_WIDTH/8) +: AW];
275				2'b11: cfg_waddr <=  s_data[$clog2(BUS_WIDTH/8) +: AW];
276				endcase
277			end end
278			// }}}
279		DMA_WAIT: begin
280			// {{{
281			o_mwb_addr <= cfg_raddr;
282			if (abort)
283				dma_state <= DMA_IDLE;
284			else if (user_halt)
285				dma_state <= DMA_IDLE;
286			else if (trigger)
287				dma_state <= DMA_READ_REQ;
288			end
289			// }}}
290		DMA_READ_REQ: begin
291			// {{{
292			if (!i_mwb_stall)
293			begin
294				// Number of read acknowledgements needed
295				if ((last_read_request)||(user_halt))
296		//((nracks == {1'b0, cfg_blocklen_sub_one})||(bus_nracks == cfg_len-1))
297					// Wishbone interruptus
298					dma_state <= DMA_READ_ACK;
299				if (cfg_incs)
300					o_mwb_addr <= o_mwb_addr
301							+ {{(AW-1){1'b0}},1'b1};
302			end
303	
304			if ((i_mwb_err)||(abort))
305				dma_state <= DMA_IDLE;
306			else if (i_mwb_ack)
307			begin
308				if (cfg_incs)
309					cfg_raddr  <= cfg_raddr
310							+ {{(AW-1){1'b0}},1'b1};
311				if (last_read_ack)
312					dma_state <= DMA_PRE_WRITE;
313			end end
314			// }}}
315		DMA_READ_ACK: begin
316			// {{{
317			if ((i_mwb_err)||(abort))
318				dma_state <= DMA_IDLE;
319			else if (i_mwb_ack)
320			begin
321				if (last_read_ack) // (nread+1 == nracks)
322					dma_state  <= DMA_PRE_WRITE;
323				if (user_halt)
324					dma_state <= DMA_IDLE;
325				if (cfg_incs)
326					cfg_raddr  <= cfg_raddr
327							+ {{(AW-1){1'b0}},1'b1};
328			end end
329			// }}}
330		DMA_PRE_WRITE: begin
331			// {{{
332			o_mwb_addr <= cfg_waddr;
333			dma_state <= (abort)? DMA_IDLE : DMA_WRITE_REQ;
334			end
335			// }}}
336		DMA_WRITE_REQ: begin
337			// {{{
338			if (!i_mwb_stall)
339			begin
340				if (last_write_request) // (nwritten == nread-1)
341					// Wishbone interruptus
342					dma_state <= DMA_WRITE_ACK;
343				if (cfg_incd)
344				begin
345					o_mwb_addr <= o_mwb_addr
346							+ {{(AW-1){1'b0}},1'b1};
347					cfg_waddr  <= cfg_waddr
348							+ {{(AW-1){1'b0}},1'b1};
349				end
350			end
351	
352			if ((i_mwb_err)||(abort))
353				dma_state <= DMA_IDLE;
354			else if ((i_mwb_ack)&&(last_write_ack))
355				dma_state <= (cfg_len <= 1) ? DMA_IDLE: DMA_WAIT;
356			else if (!cfg_len_nonzero)
357				dma_state <= DMA_IDLE;
358			end
359			// }}}
360		DMA_WRITE_ACK: begin
361			// {{{
362			if ((i_mwb_err)||(abort))
363				dma_state <= DMA_IDLE;
364			else if ((i_mwb_ack)&&(last_write_ack))
365				// (nwacks+1 == nwritten)
366				dma_state <= (cfg_len <= 1)? DMA_IDLE: DMA_WAIT;
367			else if (!cfg_len_nonzero)
368				dma_state <= DMA_IDLE;
369			end
370			// }}}
371		default:
372			dma_state <= DMA_IDLE;
373		endcase
374		// }}}
375	
376		// o_interrupt
377		// {{{
378		initial	o_interrupt = 1'b0;
379		always @(posedge i_clk)
380		if (i_reset)
381			o_interrupt <= 1'b0;
382		else
383			o_interrupt <= ((dma_state == DMA_WRITE_ACK)&&(i_mwb_ack)
384						&&(last_write_ack)
385						&&(cfg_len == {{(AW-1){1'b0}},1'b1}))
386					||((dma_state != DMA_IDLE)&&(i_mwb_err));
387		// }}}
388	
389		// cfg_len, cfg_len_nonzero
390		// {{{
391		initial	cfg_len     = 0;
392		initial	cfg_len_nonzero = 1'b0;
393		always @(posedge i_clk)
394		if (i_reset)
395		begin
396			cfg_len <= 0;
397			cfg_len_nonzero <= 1'b0;
398		end else if ((dma_state == DMA_IDLE)
399				&&(s_stb)&&(s_we)&&(s_addr == 2'b01))
400		begin
401			cfg_len   <=  s_data[(AW-1):0];
402			cfg_len_nonzero <= (|s_data[(AW-1):0]);
403		end else if ((o_mwb_cyc)&&(o_mwb_we)&&(i_mwb_ack))
404		begin
405			cfg_len <= cfg_len - 1'b1;
406			cfg_len_nonzero <= (cfg_len > 1);
407		end
408		// }}}
409	
410		// nracks
411		// {{{
412		initial	nracks   = 0;
413		always @(posedge i_clk)
414		if (i_reset)
415			nracks <= 0;
416		else if ((dma_state == DMA_IDLE)||(dma_state == DMA_WAIT))
417			nracks <= 0;
418		else if ((o_mwb_stb)&&(!o_mwb_we)&&(!i_mwb_stall))
419			nracks <= nracks + 1'b1;
420		// }}}
421	
422		// nread
423		// {{{
424		initial	nread   = 0;
425		always @(posedge i_clk)
426		if (i_reset)
427			nread <= 0;
428		else if ((dma_state == DMA_IDLE)||(dma_state == DMA_WAIT))
429			nread <= 0;
430		else if ((!o_mwb_we)&&(i_mwb_ack))
431			nread <= nread + 1'b1;
432		// }}}
433	
434		// nwritten
435		// {{{
436		initial	nwritten = 0;
437		always @(posedge i_clk)
438		if (i_reset)
439			nwritten <= 0;
440		else if ((!o_mwb_cyc)||(!o_mwb_we))
441			nwritten <= 0;
442		else if ((o_mwb_stb)&&(!i_mwb_stall))
443			nwritten <= nwritten + 1'b1;
444		// }}}
445	
446		// nwacks
447		// {{{
448		initial	nwacks   = 0;
449		always @(posedge i_clk)
450		if (i_reset)
451			nwacks <= 0;
452		else if ((!o_mwb_cyc)||(!o_mwb_we))
453			nwacks <= 0;
454		else if (i_mwb_ack)
455			nwacks <= nwacks + 1'b1;
456		// }}}
457	
458		// cfg_err
459		// {{{
460		initial	cfg_err = 1'b0;
461		always @(posedge i_clk)
462		if (i_reset)
463			cfg_err <= 1'b0;
464		else if (dma_state == DMA_IDLE)
465		begin
466			if ((s_stb)&&(s_we)&&(s_addr==2'b00))
467				cfg_err <= 1'b0;
468		end else if (((i_mwb_err)&&(o_mwb_cyc))||(abort))
469			cfg_err <= 1'b1;
470		// }}}
471	
472		// last_read_request
473		// {{{
474		initial	last_read_request = 1'b0;
475		always @(posedge i_clk)
476		if (i_reset)
477			last_read_request <= 1'b0;
478		else if ((dma_state == DMA_WAIT)||(dma_state == DMA_READ_REQ))
479		begin
480			if ((!i_mwb_stall)&&(dma_state == DMA_READ_REQ))
481			begin
482				last_read_request <=
483				(nracks + 1 == { 1'b0, cfg_blocklen_sub_one})
484					||(bus_nracks == cfg_len-2);
485			end else
486				last_read_request <=
487					(nracks== { 1'b0, cfg_blocklen_sub_one})
488					||(bus_nracks == cfg_len-1);
489		end else
490			last_read_request <= 1'b0;
491		// }}}
492	
493		assign	next_nread = nread + 1'b1;
494	
495		// last_read_ack
496		// {{{
497		initial	last_read_ack = 1'b0;
498		always @(posedge i_clk)
499		if (i_reset)
500			last_read_ack <= 0;
501		else if (dma_state == DMA_READ_REQ)
502		begin
503			if ((i_mwb_ack)&&((!o_mwb_stb)||(i_mwb_stall)))
504				last_read_ack <= (next_nread == { 1'b0, cfg_blocklen_sub_one });
505			else
506				last_read_ack <= (nread == { 1'b0, cfg_blocklen_sub_one });
507		end else if (dma_state == DMA_READ_ACK)
508		begin
509			if ((i_mwb_ack)&&((!o_mwb_stb)||(i_mwb_stall)))
510				last_read_ack <= (nread+2 == nracks);
511			else
512				last_read_ack <= (next_nread == nracks);
513		end else
514			last_read_ack <= 1'b0;
515		// }}}
516	
517		// last_write_request
518		// {{{
519		initial	last_write_request = 1'b0;
520		always @(posedge i_clk)
521		if (i_reset)
522			last_write_request <= 1'b0;
523		else if (dma_state == DMA_PRE_WRITE)
524			last_write_request <= (nread <= 1);
525		else if (dma_state == DMA_WRITE_REQ)
526		begin
527			if (i_mwb_stall)
528				last_write_request <= (nwritten >= nread-1);
529			else
530				last_write_request <= (nwritten >= nread-2);
531		end else
532			last_write_request <= 1'b0;
533		// }}}
534	
535		// last_write_ack
536		// {{{
537		initial	last_write_ack = 1'b0;
538		always @(posedge i_clk)
539		if (i_reset)
540			last_write_ack <= 1'b0;
541		else if((dma_state == DMA_WRITE_REQ)||(dma_state == DMA_WRITE_ACK))
542		begin
543			if ((i_mwb_ack)&&((!o_mwb_stb)||(i_mwb_stall)))
544				last_write_ack <= (nwacks+2 == nwritten);
545			else
546				last_write_ack <= (nwacks+1 == nwritten);
547		end else
548			last_write_ack <= 1'b0;
549		// }}}
550	
551		assign	o_mwb_cyc = (dma_state == DMA_READ_REQ)
552				||(dma_state == DMA_READ_ACK)
553				||(dma_state == DMA_WRITE_REQ)
554				||(dma_state == DMA_WRITE_ACK);
555	
556		assign	o_mwb_stb = (dma_state == DMA_READ_REQ)
557				||(dma_state == DMA_WRITE_REQ);
558	
559		assign	o_mwb_we = (dma_state == DMA_PRE_WRITE)
560				||(dma_state == DMA_WRITE_REQ)
561				||(dma_state == DMA_WRITE_ACK);
562	
563		// rdaddr
564		// {{{
565		// This is tricky.  In order for Vivado to consider dma_mem to be a
566		// proper memory, it must have a simple address fed into it.  Hence
567		// the read_address (rdaddr) register.  The problem is that this
568		// register must always be one greater than the address we actually
569		// want to read from, unless we are idling.  So ... the math is touchy.
570		//
571	
572		initial	rdaddr = 0;
573		always @(posedge i_clk)
574		if (i_reset)
575			rdaddr <= 0;
576		else if((dma_state == DMA_IDLE)||(dma_state == DMA_WAIT)
577				||(dma_state == DMA_WRITE_ACK))
578			rdaddr <= 0;
579		else if ((dma_state == DMA_PRE_WRITE)
580				||((dma_state == DMA_WRITE_REQ)&&(!i_mwb_stall)))
581			rdaddr <= rdaddr + {{(LGMEMLEN-1){1'b0}},1'b1};
582		// }}}
583	
584		// o_mwb_data
585		// {{{
586		always @(posedge i_clk)
587		// if (i_reset)
588		//	o_mwb_data <= 0;
589		// else
590		if ((dma_state != DMA_WRITE_REQ)||(!i_mwb_stall))
591			o_mwb_data <= dma_mem[rdaddr];
592	
593		always @(posedge i_clk)
594		if((dma_state == DMA_READ_REQ)||(dma_state == DMA_READ_ACK))
595			dma_mem[nread[(LGMEMLEN-1):0]] <= i_mwb_data;
596		// }}}
597	
598		// o_swb_data
599		// {{{
600		always @(posedge i_clk)
601		if (i_reset)
602			o_swb_data <= 0;
603		else casez(s_addr)
604			2'b00: o_swb_data <= {	(dma_state != DMA_IDLE), cfg_err,
605						!cfg_incs, !cfg_incd,
606						1'b0, nread,
607						cfg_on_dev_trigger, cfg_dev_trigger,
608						cfg_blocklen_sub_one
609						};
610			2'b01: o_swb_data <= { {(SLV_WIDTH-AW){1'b0}}, cfg_len  };
611			2'b10: o_swb_data <= { {(SLV_WIDTH-$clog2(BUS_WIDTH/8)-AW){1'b0}}, cfg_raddr, {($clog2(BUS_WIDTH/8)){1'b0}} };
612			2'b11: o_swb_data <= { {(SLV_WIDTH-$clog2(BUS_WIDTH/8)-AW){1'b0}}, cfg_waddr,  {($clog2(BUS_WIDTH/8)){1'b0}} };
613		endcase
614		// }}}
615	
616		// trigger
617		// {{{
618		// This causes us to wait a minimum of two clocks before starting: One
619		// to go into the wait state, and then one while in the wait state to
620		// develop the trigger.
621		initial	trigger = 1'b0;
622		always @(posedge i_clk)
623		if (i_reset)
624			trigger <= 1'b0;
625		else
626			trigger <=  (dma_state == DMA_WAIT)
627					&&((!cfg_on_dev_trigger)
628						||(i_dev_ints[cfg_dev_trigger]));
629		// }}}
630	
631		// o_swb_ack
632		// {{{
633		// Ack any access.  We'll quietly ignore any access where we are busy,
634		// but ack it anyway.  In other words, before writing to the device,
635		// double check that it isn't busy, and then write.
636		initial	o_swb_ack = 1'b0;
637		always @(posedge i_clk)
638		if (i_reset)
639			o_swb_ack <= 1'b0;
640		else if (!i_swb_cyc)
641			o_swb_ack <= 1'b0;
642		else
643			o_swb_ack <= (s_stb);
644		// }}}
645	
646		assign	o_swb_stall = 1'b0;
647	
648		// abort
649		// {{{
650		initial	abort = 1'b0;
651		always @(posedge i_clk)
652		if (i_reset)
653			abort <= 1'b0;
654		else if (dma_state == DMA_IDLE)
655			abort <= 1'b0;
656		else
657			abort <= ((s_stb)&&(s_we)
658				&&(s_addr == 2'b00)
659				&&(s_data == 32'hffed0000));
660		// }}}
661	
662		// user_halt
663		// {{{
664		initial	user_halt = 1'b0;
665		always @(posedge i_clk)
666		if (i_reset)
667			user_halt <= 1'b0;
668		else
669			user_halt <= ((user_halt)&&(dma_state != DMA_IDLE))
670				||((s_stb)&&(s_we)&&(dma_state != DMA_IDLE)
671					&&(s_addr == 2'b00)
672					&&(s_data == 32'hafed0000));
673		// }}}
674	
675		// Make verilator happy
676		// {{{
677		// verilator lint_off UNUSED
678		wire	unused;
679		assign	unused = s_cyc;
680		// verilator lint_on  UNUSED
681		// }}}
682	////////////////////////////////////////////////////////////////////////////////
683	////////////////////////////////////////////////////////////////////////////////
684	////////////////////////////////////////////////////////////////////////////////
685	//
686	// Formal properties
687	// {{{
688	////////////////////////////////////////////////////////////////////////////////
689	////////////////////////////////////////////////////////////////////////////////
690	////////////////////////////////////////////////////////////////////////////////
691	`ifdef	FORMAL
692		reg	f_past_valid;
693		wire	[LGMEMLEN:0]	f_npending;
694		initial	f_past_valid = 1'b0;
695		always @(posedge i_clk)
696			f_past_valid <= 1'b1;
697	
698		always @(*)
699		if (!f_past_valid)
700			assume(i_reset);
701	
702		always @(posedge i_clk)
703		if ((!f_past_valid)||($past(i_reset)))
704			assert(dma_state == DMA_IDLE);
705		////////////////////////////////////////////////////////////////////////
706		//
707		// Bus properties
708		// {{{
709		////////////////////////////////////////////////////////////////////////
710		//
711		//
712		parameter 	F_SLV_LGDEPTH = 3;
713		parameter 	F_MSTR_LGDEPTH = LGMEMLEN+1;
714	
715		wire [F_SLV_LGDEPTH-1:0] f_swb_nreqs, f_swb_nacks, f_swb_outstanding;
716		wire [F_MSTR_LGDEPTH-1:0] f_mwb_nreqs, f_mwb_nacks, f_mwb_outstanding;
717	
718		fwb_slave #(
719			// {{{
720			.AW(2), .DW(SLV_WIDTH), .F_MAX_STALL(0), .F_MAX_ACK_DELAY(2),
721				.F_LGDEPTH(F_SLV_LGDEPTH)
722			// }}}
723		) control_port(
724			// {{{
725			i_clk, i_reset,
726			i_swb_cyc, i_swb_stb, i_swb_we, i_swb_addr, i_swb_data,4'b1111,
727				o_swb_ack, o_swb_stall, o_swb_data, 1'b0,
728				f_swb_nreqs, f_swb_nacks, f_swb_outstanding
729			// }}}
730		);
731	
732		always @(*)
733			assert(o_swb_stall == 0);
734	
735		generate if (OPT_DELAY_BUS_ACCESS)
736		begin : F_DELAY_BUS
737			// {{{
738			always @(*)
739			if ((!i_reset)&&(i_swb_cyc))
740			begin
741				if ((!s_stb)&&(!o_swb_ack))
742				begin
743					assert(f_swb_outstanding == 0);
744				end else if ((s_stb)&&(!o_swb_ack))
745				begin
746					assert(f_swb_outstanding == 1);
747				end else if ((!s_stb)&&(o_swb_ack))
748				begin
749					assert(f_swb_outstanding == 1);
750				end else if ((s_stb)&&(o_swb_ack))
751					assert(f_swb_outstanding == 2);
752			end
753			// }}}
754		end else begin
755			// {{{
756			always @(*)
757			if (!i_reset)
758				assert(f_swb_outstanding == (o_swb_ack ? 1:0));
759			// }}}
760		end endgenerate
761	
762		fwb_master #(
763			// {{{
764			.AW(AW), .DW(BUS_WIDTH), .F_MAX_STALL(4), .F_MAX_ACK_DELAY(8),
765				.F_LGDEPTH(F_MSTR_LGDEPTH),
766				.F_OPT_RMW_BUS_OPTION(1'b1),
767				.F_OPT_DISCONTINUOUS(1'b0),
768				.F_OPT_SOURCE(1'b1)
769			// }}}
770		) external_bus(
771			// {{{
772			i_clk, i_reset,
773			o_mwb_cyc, o_mwb_stb, o_mwb_we, o_mwb_addr, o_mwb_data,
774				{(BUS_WIDTH/8){1'b1}},
775				i_mwb_ack, i_mwb_stall, i_mwb_data, i_mwb_err,
776				f_mwb_nreqs, f_mwb_nacks, f_mwb_outstanding
777			// }}}
778		);
779	
780		always @(posedge i_clk)
781		if ((f_past_valid)&&($past(dma_state == DMA_IDLE)))
782			assert(o_mwb_cyc == 1'b0);
783	
784		always @(*)
785		if ((o_mwb_cyc)&&(!o_mwb_we))
786		begin
787			assert(nracks == f_mwb_nreqs);
788			assert(nread == f_mwb_nacks);
789		end
790	
791		always @(*)
792		if ((o_mwb_cyc)&&(o_mwb_we))
793		begin
794			assert(nwacks   == f_mwb_nacks);
795			assert(nwritten == f_mwb_nreqs);
796		end
797	
798		// }}}
799	
800		always @(posedge i_clk)
801		if ((f_past_valid)&&($past(abort))&&($past(dma_state != DMA_IDLE)))
802			assert(dma_state == DMA_IDLE);
803	
804		always @(posedge i_clk)
805		if ((f_past_valid)&&($past(o_mwb_cyc))&&(o_mwb_cyc)&&(
806				((  !cfg_incs)&&(!o_mwb_we))
807				||((!cfg_incd)&&( o_mwb_we))))
808		begin
809			assert(o_mwb_addr == $past(o_mwb_addr));
810		end
811	
812		always @(posedge i_clk)
813		if ((f_past_valid)&&($past(o_mwb_cyc))&&(
814				((!cfg_incs)||($past(o_mwb_we))||(!$past(i_mwb_ack)))))
815			assert(cfg_raddr == $past(cfg_raddr));
816	
817		always @(posedge i_clk)
818		if ((f_past_valid)&&(dma_state == DMA_WRITE_REQ))
819			assert(cfg_waddr == o_mwb_addr);
820	
821		always @(posedge i_clk)
822		if ((f_past_valid)&&(!$past(i_reset))
823				&&($past(o_mwb_stb))&&(!$past(i_mwb_stall)))
824		begin
825			assert(   ((!cfg_incs)&&(!$past(o_mwb_we)))
826				||((!cfg_incd)&&( $past(o_mwb_we)))
827				||(o_mwb_addr==$past(o_mwb_addr)+1'b1));
828		end
829	
830		always @(posedge i_clk)
831		if ((f_past_valid)&&(!$past(o_mwb_cyc))&&(o_mwb_cyc))
832		begin
833			if (o_mwb_we)
834			begin
835				assert(o_mwb_addr == cfg_waddr);
836			end else
837				assert(o_mwb_addr == cfg_raddr);
838		end
839	
840		always @(*)
841			assert(cfg_len_nonzero == (cfg_len != 0));
842	
843		always @(posedge i_clk)
844		if ((f_past_valid)&&($past(i_reset)))
845		begin
846			assert(cfg_len == 0);
847			assert(!cfg_len_nonzero);
848		end else if ((f_past_valid)&&($past(o_mwb_cyc)))
849		begin
850			if (($past(i_mwb_ack))&&($past(o_mwb_we)))
851			begin
852				assert(cfg_len == $past(cfg_len)-1'b1);
853			end else
854				assert(cfg_len == $past(cfg_len));
855		end else if ((f_past_valid)&&(($past(dma_state) != DMA_IDLE)
856				||(!$past(s_stb))||(!$past(s_we))
857				||($past(s_addr)!=2'b01)))
858			assert(cfg_len == $past(cfg_len));
859	
860		always @(posedge i_clk)
861		if ((f_past_valid)&&($past(o_mwb_cyc))&&($past(cfg_len == 0))
862				&&(!$past(user_halt)))
863		begin
864			assert(cfg_len == 0);
865			assert((dma_state != $past(dma_state))||(!o_mwb_cyc));
866		end
867	
868		always @(posedge i_clk)
869		if (cfg_len == 0)
870			assert(!o_mwb_stb);
871	
872		always @(posedge i_clk)
873		if ((f_past_valid)&&(!$past(i_reset))&&($past(dma_state) != DMA_IDLE))
874		begin
875			assert(cfg_incs == $past(cfg_incs));
876			assert(cfg_incd == $past(cfg_incd));
877			assert(cfg_blocklen_sub_one == $past(cfg_blocklen_sub_one));
878		end
879	
880		always @(posedge i_clk)
881		if ((f_past_valid)&&($past(dma_state) == DMA_IDLE))
882			assert(cfg_len_nonzero == (cfg_len != 0));
883	
884		always @(posedge i_clk)
885		if ((f_past_valid)&&(!$past(o_mwb_cyc))||(!$past(o_mwb_we)))
886			assert((nwritten == 0)&&(nwacks == 0));
887		always @(posedge i_clk)
888		if ((o_mwb_cyc)&&(!o_mwb_we))
889			assert(bus_nracks <= cfg_len);
890	
891		always @(posedge i_clk)
892		if ((o_mwb_cyc)&&(!o_mwb_we))
893			assert(nread <= nracks);
894	
895		always @(posedge i_clk)
896		if ((o_mwb_cyc)&&(o_mwb_we))
897			assert(nwritten-nwacks
898				+((o_mwb_stb)? 1'b1:1'b0)
899				- f_mwb_outstanding
900				// -((i_mwb_ack)? 1'b1:1'b0)
901				<= cfg_len);
902		always @(*)
903			assert(f_mwb_outstanding
904				+ ((o_mwb_stb)? 1'b1:1'b0) <= cfg_len);
905	
906		wire	[LGMEMLEN:0]	f_cfg_blocklen;
907		assign	f_cfg_blocklen = { 1'b0, cfg_blocklen_sub_one}  + 1'b1;
908	
909		always @(*)
910		if (dma_state == DMA_WAIT)
911			assert(cfg_len > 0);
912	
913		always @(*)
914		if ((o_mwb_stb)&&(o_mwb_we))
915			assert(nread == nracks);
916	
917		always @(*)
918		if (o_mwb_stb)
919			assert(nwritten <= cfg_blocklen_sub_one);
920	
921		always @(posedge i_clk)
922			assert(nwritten <= f_cfg_blocklen);
923	
924		always @(*)
925		if ((o_mwb_stb)&&(!o_mwb_we))
926		begin
927			assert(nracks < f_cfg_blocklen);
928		end else
929			assert(nracks <= f_cfg_blocklen);
930	
931		always @(*)
932		if ((o_mwb_cyc)&&(i_mwb_ack)&&(!o_mwb_we))
933			assert(nread < f_cfg_blocklen);
934	
935		always @(*)
936			assert(nread <= nracks);
937	
938		always @(*)
939		if ((o_mwb_cyc)&&(o_mwb_we)&&(!user_halt))
940			assert(nread == nracks);
941	
942		always @(*)
943		if ((o_mwb_cyc)&&(o_mwb_we))
944			assert(nwritten >= nwacks);
945	
946		always @(*)
947		if (dma_state == DMA_WRITE_REQ)
948			assert(last_write_request == (nwritten == nread-1));
949	
950		always @(*)
951			assert(nwritten >= nwacks);
952	
953		always @(*)
954			assert(nread >= nwritten);
955	
956		always @(*)
957			assert(nracks >= nread);
958	
959		assign	f_npending = nread-nwacks;
960	
961		always @(*)
962		if (dma_state != DMA_IDLE)
963			assert({ {(AW-LGMEMLEN-1){1'b0}}, f_npending} <= cfg_len);
964	
965		always @(posedge i_clk)
966		begin
967			assert(cfg_len_nonzero == (cfg_len != 0));
968			if ((f_past_valid)&&($past(dma_state != DMA_IDLE))&&($past(cfg_len == 0)))
969				assert(cfg_len == 0);
970		end
971	`endif
972	// }}}
973	endmodule
