372		);
373	
374		wbarbiter #(
375			// {{{
376			.DW(BUS_WIDTH), .AW(AW), .OPT_ZERO_ON_IDLE(OPT_LOWPOWER)
377			// }}}
378		) u_arbiter (
379			// {{{
380			.i_clk(i_clk), .i_reset(i_reset),
381			//
382			.i_a_cyc(mm2s_rd_cyc),		.i_a_stb(mm2s_rd_stb),
383			.i_a_we(mm2s_rd_we),		.i_a_adr(mm2s_rd_addr),
384			.i_a_dat((OPT_LOWPOWER) ? mm2s_rd_data : s2mm_wr_data),
385							.i_a_sel(mm2s_rd_sel),
386			.o_a_stall(mm2s_rd_stall),	.o_a_ack(mm2s_rd_ack),
387			.o_a_err(mm2s_rd_err),
388			//
389			.i_b_cyc(s2mm_wr_cyc),		.i_b_stb(s2mm_wr_stb),
390			.i_b_we(s2mm_wr_we),		.i_b_adr(s2mm_wr_addr),
391			.i_b_dat(s2mm_wr_data),		.i_b_sel(s2mm_wr_sel),
392			.o_b_stall(s2mm_wr_stall),	.o_b_ack(s2mm_wr_ack),
393			.o_b_err(s2mm_wr_err),
394			//
395			.o_cyc(wb_cyc),			.o_stb(wb_stb),
396			.o_we(wb_we),			.o_adr(wb_addr),
397			.o_dat(wb_data),		.o_sel(wb_sel),
398			.i_stall(wb_stall),		.i_ack(wb_ack),
399			.i_err(wb_err)
400			// }}}
401		);
402	
403		assign	o_mwb_cyc  = wb_cyc;
404		assign	o_mwb_stb  = wb_stb;
405		assign	o_mwb_we   = wb_we;
406		assign	o_mwb_addr = wb_addr;
407		assign	o_mwb_data = wb_data;
408		assign	o_mwb_sel  = wb_sel;
409		assign	wb_stall   = i_mwb_stall;
410		assign	wb_ack     = i_mwb_ack;
411		assign	wb_idata   = i_mwb_data;
412		assign	wb_err     = i_mwb_err;
413	
414		assign	read_addr  = { mm2s_rd_addr, {($clog2(BUS_WIDTH/8)){1'b0}} };
415		assign	write_addr = { s2mm_wr_addr, {($clog2(BUS_WIDTH/8)){1'b0}} };
416	
417		// Make verilator happy
418		// {{{
419		// verilator coverage_off
420		// verilator lint_off UNUSED
421		wire	unused;
422		assign	unused = &{ 1'b0, ign_sfifo_fill, mm2s_rd_data, rx_ready,
423					s2mm_transferlen };
424		// verilator lint_on  UNUSED
425		// verilator coverage_on
426		// }}}
427	////////////////////////////////////////////////////////////////////////////////
428	////////////////////////////////////////////////////////////////////////////////
429	////////////////////////////////////////////////////////////////////////////////
430	//
431	// Formal properties
432	// {{{
433	////////////////////////////////////////////////////////////////////////////////
434	////////////////////////////////////////////////////////////////////////////////
435	////////////////////////////////////////////////////////////////////////////////
436	`ifdef	FORMAL
437		reg	f_past_valid;
438	
439		initial	f_past_valid = 1'b0;
440		always @(posedge i_clk)
441			f_past_valid <= 1'b1;
442	
443		always @(*)
444		if (!f_past_valid)
445			assume(i_reset);
446	`endif
447	// }}}
448	endmodule
