41	// }}}
42	module	zipdma_mm2s #(
43			// {{{
44			parameter	ADDRESS_WIDTH = 30,
45			parameter	BUS_WIDTH = 64,
46			parameter	LGLENGTH = 10,
47			parameter [0:0]	OPT_LITTLE_ENDIAN = 1'b0,
48			parameter [0:0]	OPT_LOWPOWER = 1'b0,
49			parameter [0:0] OPT_FIRSTBEAT_TRIM = 1'b0,
50			// Abbreviations
51			localparam	DW = BUS_WIDTH,
52			localparam	AW = ADDRESS_WIDTH-$clog2(DW/8)
53			// }}}
54		) (
55			// {{{
56			input	wire	i_clk, i_reset,
57			// Configuration
58			// {{{
59			input	wire			i_request,
60			output	reg			o_busy, o_err,
61			input	wire			i_inc,
62			// # of transferred byte per beat
63			input	wire	[1:0]		i_size,
64			input	wire	[LGLENGTH:0]	i_transferlen,
65			input wire [ADDRESS_WIDTH-1:0]	i_addr,	// Byte address
66			// }}}
67			// Wishbone master interface
68			// {{{
69			output	reg			o_rd_cyc, o_rd_stb,
70			// Verilator coverage_off
71			output	wire			o_rd_we,
72			// Verilator coverage_on
73			output	reg	[AW-1:0]	o_rd_addr,
74			// Verilator coverage_off
75			output	wire	[DW-1:0]	o_rd_data,
76			// Verilator coverage_on
77			output	reg	[DW/8-1:0]	o_rd_sel,
78			input	wire			i_rd_stall,
79			input	wire			i_rd_ack,
80			input	wire	[DW-1:0]	i_rd_data,
81			input	wire			i_rd_err,
82			// }}}
83			// Outgoing Stream interface
84			// {{{
85			output	wire			M_VALID,
86			input	wire			M_READY,	// *MUST* be 1
87			output	wire	[DW-1:0]	M_DATA,
88			// How many bytes are valid?
89			output	wire [$clog2(DW/8):0]	M_BYTES,
90			output	wire			M_LAST
91			// }}}
92			// }}}
93		);
94	
95		// Local declarations
96		// {{{
97		// size prefix is # of valid bytes in the beat (one clk cycle)
98		// difference between _size and _len is that "size" references the
99		// current beat, whereas _len references the whole transfer.  _sel
100		// references which data byte lanes are valid (like WSTRB from AXI
101		// interface)
102		//
103		localparam [1:0]	SZ_BYTE = 2'b11,
104					SZ_16B  = 2'b10,
105					SZ_32B  = 2'b01,
106					SZ_BUS  = 2'b00;
107		localparam	WBLSB = $clog2(DW/8);
108		reg	[WBLSB:0]	nxtstb_size, rdstb_size, rdack_size,
109					first_size, last_size;
110		reg				r_wrap;
111		reg	[ADDRESS_WIDTH:0]	next_addr;
112		reg	[ADDRESS_WIDTH-1:0]	last_request_addr;
113		reg	[WBLSB-1:0]	subaddr, rdack_subaddr;
114		reg	[DW/8-1:0]	nxtstb_sel, first_sel, first_sel_no_shift,
115					base_sel, ibase_sel;
116		reg	[LGLENGTH:0]	wb_outstanding;
117	
118		reg	[WBLSB+1:0]	fill, next_fill;
119	
120		reg			m_valid, m_last;
121		reg	[DW-1:0]	sreg;
122		reg	[WBLSB:0]	m_bytes;
123	
124		reg	[LGLENGTH:0]	rdstb_len, rdack_len;
125	
126		reg	[WBLSB-1:0]	pre_shift;
127		reg	[DW-1:0]	pre_shifted_data;
128	
129		reg			r_inc;
130		reg	[1:0]		r_size;
131		reg	[LGLENGTH:0]	r_transferlen;
132		reg	[ADDRESS_WIDTH-1:0]	r_addr;
133		// }}}
134	
135		assign	o_rd_we = 1'b0;
136		assign	o_rd_data = {(DW){1'b0}};
137	
138		// Copy the configuration whenever i_request && !o_busy
139		// {{{
140		always @(posedge i_clk)
141		if (!o_busy && (!OPT_LOWPOWER || i_request))
142		begin
143			r_inc  <= i_inc;
144			r_size <= i_size;
145			r_transferlen <= i_transferlen;
146			r_addr <= i_addr;
147		end
148		// }}}
149	
150		// nxtstb_size
151		// {{{
152		generate if (BUS_WIDTH > 32)
153		begin : GEN_NXTSTB_SIZE
154			// {{{
155			always @(*)
156			begin
157				first_size = 0;
158				case(i_size)
159				SZ_BYTE: first_size = 1;
160				SZ_16B:  first_size = (i_addr[0]) ? 1 : 2;
161				// Verilator lint_off WIDTH
162				SZ_32B:  first_size = 4 - i_addr[1:0];
163				SZ_BUS:  first_size = (DW/8)-i_addr[WBLSB-1:0];
164				// Verilator lint_on  WIDTH
165				endcase
166	
167				if ({{ (LGLENGTH-WBLSB){1'b0}}, first_size } > i_transferlen)
168					first_size = i_transferlen[WBLSB:0];
169			end
170	
171			always @(*)
172			begin
173				nxtstb_size = rdstb_size;
174				last_size = r_addr[WBLSB-1:0]+ r_transferlen[WBLSB-1:0];
175	
176				case(r_size)
177				SZ_BYTE: nxtstb_size = 1;
178				// Verilator lint_off WIDTH
179				SZ_16B: if (r_transferlen == 2)
180						nxtstb_size = 2 - r_addr[0];
181					else if (r_transferlen == 3)
182						nxtstb_size = r_addr[0] + 1;
183					else
184						nxtstb_size = (rdstb_len == 3) ? 1 : 2;
185				SZ_32B: begin
186					last_size[WBLSB:2] = 0;
187					if (r_transferlen < 8)
188					begin
189						if (r_transferlen[1:0] + r_addr[1:0] == 0)
190							nxtstb_size = 4;
191						else
192							nxtstb_size = (4 > rdstb_len - rdstb_size) ? last_size : 4;
193					end else
194						nxtstb_size = (rdstb_len >= 4 && rdstb_len < 8)
195							? (rdstb_len - 4) : 4;
196					end
197				SZ_BUS: begin
198					nxtstb_size = (DW/8);
199					if (DW/8 > rdstb_len - rdstb_size)
200						nxtstb_size= { 1'b0,rdstb_len[WBLSB:0] }
201							- { 1'b0, rdstb_size[WBLSB:0]};
202					end
203				// Verilator lint_on  WIDTH
204				endcase
205			end
206			// }}}
207		end else begin : STD_NXTSTB_SIZE
208			// {{{
209			always @(*)
210			begin
211				first_size = 0;
212				case(i_size)
213				SZ_BYTE: first_size = 1;
214				SZ_16B:  first_size = (i_addr[0]) ? 1:2;
215				// Verilator lint_off WIDTH
216				default:
217					first_size = (DW/8)-i_addr[WBLSB-1:0];
218				endcase
219	
220				if (first_size > i_transferlen)
221					first_size = i_transferlen;
222				// Verilator lint_on  WIDTH
223			end
224	
225			always @(*)
226			begin
227				nxtstb_size = rdstb_size;
228				last_size = r_addr[WBLSB-1:0]+r_transferlen[WBLSB-1:0];
229	
230				casez(r_size)
231				SZ_BYTE: nxtstb_size = 1;
232				// Verilator lint_off WIDTH
233				SZ_16B: if (r_transferlen == 2)
234						nxtstb_size = 2 - r_addr[0];
235					else if (r_transferlen == 3)
236						nxtstb_size = r_addr[0] + 1;
237					else
238						nxtstb_size = (rdstb_len == 3) ? 1 : 2;
239				default: begin
240					last_size[WBLSB:2] = 0;
241					if (r_transferlen < 8)
242					begin
243						if (r_transferlen[1:0] + r_addr[1:0] == 0)
244							nxtstb_size = 4;
245						else
246							nxtstb_size = (4 > rdstb_len - rdstb_size) ? last_size : 4;
247					end else
248						nxtstb_size = (rdstb_len >= 4
249								&& rdstb_len < 8)
250							? (rdstb_len - 4) : 4;
251					end
252					// Verilator lint_on  WIDTH
253				endcase
254			end
255			// }}}
256		end endgenerate
257		// }}}
258	
259		// next_addr
260		// {{{
261		always @(*)
262		begin
263			next_addr = { 1'b0, o_rd_addr, subaddr };
264	
265			if (o_rd_stb && !i_rd_stall && r_inc)
266				next_addr = next_addr
267				+ { {(ADDRESS_WIDTH-WBLSB-1){1'b0}}, rdstb_size };
268		end
269		// }}}
270	
271		// o_rd_cyc, o_rd_stb, o_busy, o_err, rdstb_len, rdstb_size
272		// {{{
273		initial	{ o_rd_cyc, o_rd_stb } = 2'b00;
274		initial	{ o_busy, o_err } = 2'b00;
275		always @(posedge i_clk)
276		if (i_reset)
277		begin
278			// {{{
279			o_rd_cyc <= 1'b0;
280			o_rd_stb <= 1'b0;
281			{ o_rd_addr, subaddr } <= 0;
282	
283			rdstb_size <= 0;
284			rdstb_len  <= 0;
285			o_busy     <= 0;
286			o_err      <= 0;
287			// }}}
288		end else if ((o_rd_cyc && i_rd_err) || o_err)
289		begin
290			// {{{
291			o_rd_cyc <= 1'b0;
292			o_rd_stb <= 1'b0;
293			{ o_rd_addr, subaddr } <= 0;
294	
295			rdstb_size <= 0;
296			rdstb_len  <= 0;
297	
298			o_busy <= o_rd_cyc && i_rd_err;
299			o_err  <= o_rd_cyc && i_rd_err;
300			// }}}
301		end else if (!o_busy)
302		begin
303			// {{{
304			o_rd_cyc <= i_request;
305			o_rd_stb <= i_request;
306			o_busy   <= i_request;
307			o_err    <= 0;
308	
309			rdstb_size <= 0;
310			rdstb_len  <= 0;
311			if (!OPT_LOWPOWER || i_request)
312			begin
313				{ o_rd_addr, subaddr } <= i_addr;
314	
315				// rdstb_size
316				rdstb_size <= first_size;
317	
318				// rdstb_len
319				rdstb_len <= i_transferlen;
320			end
321			// }}}
322		end else begin
323			if (!i_rd_stall)
324				o_rd_stb <= 1'b0;
325	
326			if (rdstb_len > { {(LGLENGTH-WBLSB){1'b0}}, rdstb_size })
327			begin
328				if (r_wrap || next_addr[ADDRESS_WIDTH])
329					{ o_err, o_rd_cyc, o_rd_stb } <= 3'b100;
330				else
331					o_rd_stb <= 1'b1;
332			end
333	
334			if (o_rd_stb && !i_rd_stall)
335			begin
336				// {{{
337				if (rdstb_len <= { {(LGLENGTH-WBLSB){1'b0}}, rdstb_size })
338				begin
339					rdstb_len <= 0;
340				end else begin
341					rdstb_len <= rdstb_len
342						- { {(LGLENGTH-WBLSB){1'b0}}, rdstb_size };
343				end
344	
345				// rdstb_size
346				rdstb_size <= nxtstb_size;
347	
348				{ o_rd_addr, subaddr } <= next_addr[ADDRESS_WIDTH-1:0];
349				// }}}
350			end
351	
352			if (wb_outstanding == (i_rd_ack ? 1:0) && !o_rd_stb)
353				o_rd_cyc <= 1'b0;
354	
355			if (m_valid && m_last)
356				o_busy <= 0;
357		end
358	
359		initial	r_wrap = 1'b0;
360		always @(posedge i_clk)
361		if (i_reset || (o_rd_cyc && i_rd_err) || o_err || !o_busy)
362			r_wrap <= 1'b0;
363		else if (o_rd_stb && !i_rd_stall)
364			r_wrap <= next_addr[ADDRESS_WIDTH];
365	`ifdef	FORMAL
366		always @(*)
367		if (o_busy && m_valid && m_last)
368		begin
369			assert(rdack_len == 0);
370			assert(fill == m_bytes);
371		end
372	`endif
373		// }}}
374	
375		// o_rd_sel
376		// {{{
377	
378		// ibase_sel
379		generate if (BUS_WIDTH > 32)
380		begin : GEN_STRB
381			// {{{
382			always @(*)
383			begin
384				ibase_sel = 0;
385	
386				if (OPT_LITTLE_ENDIAN)
387				begin
388					// {{{
389					// Verilator coverage_off
390					case(i_size)
391					SZ_BYTE: ibase_sel = {{(DW/8-1){1'b0}}, 1'b1} << i_addr[WBLSB-1:0];
392					SZ_16B: ibase_sel = {{(DW/8-2){1'b0}}, 2'h3} << {i_addr[WBLSB-1:1], 1'b0 };
393					SZ_32B: ibase_sel = {{(DW/8-4){1'b0}}, 4'b1111} << {i_addr[WBLSB-1:2], 2'b0 };
394					SZ_BUS: ibase_sel = {(DW/8){1'b1}};
395					endcase
396					// Verilator coverage_on
397					// }}}
398				end else begin
399					// {{{
400					case(i_size)
401					SZ_BYTE: ibase_sel = {1'h1, {(DW/8-1){1'b0}} } >> i_addr[WBLSB-1:0];
402					SZ_16B: ibase_sel = {2'h3, {(DW/8-2){1'b0}} } >> {i_addr[WBLSB-1:1], 1'b0 };
403					SZ_32B: ibase_sel = {4'hf, {(DW/8-4){1'b0}} } >> {i_addr[WBLSB-1:2], 2'b0 };
404					SZ_BUS: ibase_sel = {(DW/8){1'b1}};
405					endcase
406					// }}}
407				end
408			end
409			// }}}
410		end else begin : MIN_STRB
411			// {{{
412			always @(*)
413			if (OPT_LITTLE_ENDIAN)
414			begin
415				// {{{
416				// Verilator coverage_off
417				case(i_size)
418				SZ_BYTE: ibase_sel = {{(DW/8-1){1'b0}}, 1'b1} << i_addr[WBLSB-1:0];
419				SZ_16B: ibase_sel = {{(DW/8-2){1'b0}}, 2'h3} << {i_addr[WBLSB-1:1], 1'b0 };
420				default: ibase_sel = {(DW/8){1'b1}};
421				endcase
422				// Verilator coverage_on
423				// }}}
424			end else begin
425				// {{{
426				case(i_size)
427				SZ_BYTE: ibase_sel= {1'h1, {(DW/8-1){1'b0}} } << i_addr[WBLSB-1:0];
428				SZ_16B: ibase_sel = {2'h3, {(DW/8-2){1'b0}} } << {i_addr[WBLSB-1:1], 1'b0 };
429				default: ibase_sel = {(DW/8){1'b1}};
430				endcase
431				// }}}
432			end
433			// }}}
434		end endgenerate
435	
436		always @(posedge i_clk)
437		if (i_reset || (o_rd_cyc && i_rd_err))
438		begin
439			base_sel <= 0;
440		end else if (!o_busy)
441		begin
442			base_sel <= 0;
443			if (i_request || !OPT_LOWPOWER)
444				base_sel <= ibase_sel;
445		end else if (o_rd_stb && !i_rd_stall)
446			base_sel <= nxtstb_sel;
447	
448		// nxtstb_sel
449		// {{{
450		generate if (DW == 32)
451		begin : GEN_NXTSTB_SEL
452			// {{{
453			always @(*)
454			if (OPT_LITTLE_ENDIAN)
455			begin
456				// Verilator coverage_off
457				case(r_size)
458				SZ_BYTE: nxtstb_sel = { base_sel[DW/8-2:0], base_sel[DW/8-1] };
459				SZ_16B:  nxtstb_sel = { base_sel[DW/8-3:0], base_sel[DW/8-1:DW/8-2] };
460				default: nxtstb_sel = {(DW/8){1'b1}};
461				endcase
462	
463				if (!r_inc)
464					nxtstb_sel = base_sel;
465				// Verilator coverage_on
466			end else begin
467				case(r_size)
468				SZ_BYTE: nxtstb_sel = { base_sel[0:0], base_sel[DW/8-1:1] };
469				SZ_16B:  nxtstb_sel = { base_sel[1:0], base_sel[DW/8-1:2] };
470				default:
471					nxtstb_sel = {(DW/8){1'b1}};
472				endcase
473	
474				if (!r_inc)
475					nxtstb_sel = base_sel;
476			end
477			// }}}
478		end else begin : GEN_WIDE_NXTSTB_SEL
479			always @(*)
480			if (OPT_LITTLE_ENDIAN)
481			begin
482				// Verilator coverage_off
483				case(r_size)
484				SZ_BYTE: nxtstb_sel = { base_sel[DW/8-2:0], base_sel[DW/8-1] };
485				SZ_16B:  nxtstb_sel = { base_sel[DW/8-3:0], base_sel[DW/8-1:DW/8-2] };
486				SZ_32B:  nxtstb_sel = { base_sel[DW/8-5:0], base_sel[DW/8-1:DW/8-4] };
487				SZ_BUS:  nxtstb_sel = {(DW/8){1'b1}};
488				endcase
489	
490				if (!r_inc)
491					nxtstb_sel = base_sel;
492				// Verilator coverage_on
493			end else begin
494				case(r_size)
495				SZ_BYTE: nxtstb_sel = { base_sel[0:0], base_sel[DW/8-1:1] };
496				SZ_16B:  nxtstb_sel = { base_sel[1:0], base_sel[DW/8-1:2] };
497				SZ_32B:  nxtstb_sel = { base_sel[3:0], base_sel[DW/8-1:4] };
498				SZ_BUS:  nxtstb_sel = {(DW/8){1'b1}};
499				endcase
500	
501				if (!r_inc)
502					nxtstb_sel = base_sel;
503			end
504		end endgenerate
505		// }}}
506	
507		// first_sel
508		generate if (BUS_WIDTH > 32)
509		begin : GEN_FIRST_SEL
510			// {{{
511			always @(*)
512			begin
513				first_sel_no_shift = 0;
514				first_sel = 0;
515	
516				// Verilator lint_off WIDTH
517				if (!OPT_FIRSTBEAT_TRIM || i_transferlen >= DW/8)
518					first_sel_no_shift = -1;
519				else if (OPT_LITTLE_ENDIAN)
520					first_sel_no_shift = (1 << i_transferlen) - 1;
521				else
522					first_sel_no_shift = ({(DW/8){1'b1}} << (DW/8 - i_transferlen));
523				// Verilator lint_on  WIDTH
524	
525				if (OPT_LITTLE_ENDIAN)
526				begin
527					// {{{
528					// Verilator coverage_off
529					case(i_size)
530					SZ_BYTE: first_sel = {{(DW/8-1){1'b0}}, 1'b1} << i_addr[WBLSB-1:0];
531					SZ_16B: begin
532						first_sel_no_shift = first_sel_no_shift << i_addr[0];
533						first_sel_no_shift[DW/8-1:2] = 0;
534						first_sel = first_sel_no_shift << {i_addr[WBLSB-1:1], 1'b0 };
535						end
536					SZ_32B: begin
537						first_sel_no_shift = first_sel_no_shift << i_addr[1:0];
538						first_sel_no_shift[DW/8-1:4] = 0;
539						first_sel = first_sel_no_shift << {i_addr[WBLSB-1:2], 2'b00 };
540						end
541					SZ_BUS: first_sel = first_sel_no_shift << i_addr[WBLSB-1:0];
542					endcase
543					// Verilator coverage_on
544					// }}}
545				end else begin
546					// {{{
547					case(i_size)
548					SZ_BYTE: first_sel = {1'b1, {(DW/8-1){1'b0}} } >> i_addr[WBLSB-1:0];
549					SZ_16B: begin
550						first_sel_no_shift = first_sel_no_shift >> i_addr[0];
551						first_sel_no_shift[DW/8-3:0] = 0;
552						first_sel = first_sel_no_shift >> {i_addr[WBLSB-1:1], 1'b0 };
553						end
554					SZ_32B: begin
555						first_sel_no_shift = first_sel_no_shift >> i_addr[1:0];
556						first_sel_no_shift[DW/8-5:0] = 0;
557						first_sel = first_sel_no_shift >> {i_addr[WBLSB-1:2], 2'b00 };
558						end
559					SZ_BUS: first_sel = first_sel_no_shift >> i_addr[WBLSB-1:0];
560					endcase
561					// }}}
562				end
563			end
564			// }}}
565		end else begin : MIN_FIRST_SEL
566			// {{{
567			always @(*)
568			begin
569				first_sel_no_shift = 0;
570				first_sel = 0;
571	
572				if (!OPT_FIRSTBEAT_TRIM || i_transferlen >= DW/8)
573					first_sel_no_shift = -1;
574				else if (OPT_LITTLE_ENDIAN)
575					first_sel_no_shift = (1 << i_transferlen) - 1;
576				else
577					first_sel_no_shift = ({(DW/8){1'b1}} << (DW/8 - i_transferlen));
578	
579				if (OPT_LITTLE_ENDIAN)
580				begin
581					// {{{
582					// Verilator coverage_off
583					case(i_size)
584					SZ_BYTE: first_sel = {{(DW/8-1){1'b0}}, 1'b1} << i_addr[WBLSB-1:0];
585					SZ_16B: begin
586						first_sel_no_shift = first_sel_no_shift << i_addr[0];
587						first_sel_no_shift[DW/8-1:2] = 0;
588						first_sel = first_sel_no_shift << {i_addr[WBLSB-1:1], 1'b0 };
589						end
590					default: first_sel = first_sel_no_shift << i_addr[WBLSB-1:0];
591					endcase
592					// Verilator coverage_on
593					// }}}
594				end else begin
595					// {{{
596					case(i_size)
597					SZ_BYTE: first_sel = {1'b1, {(DW/8-1){1'b0}} } >> i_addr[WBLSB-1:0];
598					SZ_16B: begin
599						first_sel_no_shift = first_sel_no_shift >> i_addr[0];
600						first_sel_no_shift[DW/8-3:0] = 0;
601						first_sel = first_sel_no_shift >> {i_addr[WBLSB-1:1], 1'b0 };
602						end
603					default: first_sel = first_sel_no_shift >> i_addr[WBLSB-1:0];
604					endcase
605					// }}}
606				end
607			end
608			// }}}
609		end endgenerate
610	
611		// o_rd_sel
612		always @(posedge i_clk)
613		if (i_reset || (o_rd_cyc && i_rd_err))
614		begin
615			o_rd_sel   <= 0;
616		end else if (!o_busy)
617		begin
618			// {{{
619			o_rd_sel <= {(DW/8){1'b0}};
620	
621			if (!OPT_LOWPOWER || i_request)
622				o_rd_sel <= first_sel;
623			// }}}
624		end else if (o_rd_stb && !i_rd_stall)
625			o_rd_sel <= nxtstb_sel;
626		// }}}
627	
628		// wb_outstanding
629		// {{{
630		initial	wb_outstanding = 0;
631		always @(posedge i_clk)
632		if (i_reset || !o_rd_cyc || i_rd_err)
633			wb_outstanding <= 0;
634			// wb_pipeline_full <= 1'b0;
635		else case({ (o_rd_stb && !i_rd_stall), i_rd_ack })
636		2'b10: wb_outstanding <= wb_outstanding + 1;
637		2'b01: wb_outstanding <= wb_outstanding - 1;
638		default: begin end
639		endcase
640		// }}}
641	
642		// rdack_subaddr
643		// {{{
644		always @(posedge i_clk)
645		if (!o_busy)
646		begin
647			if (!OPT_LOWPOWER || i_request)
648				rdack_subaddr <= i_addr[WBLSB-1:0];
649		end else if (i_rd_ack)
650		begin
651			// Verilator lint_off WIDTH
652			if (r_inc)
653				rdack_subaddr <= rdack_subaddr + rdack_size;
654			else case(r_size)
655			SZ_BYTE: begin end
656			SZ_16B: rdack_subaddr[  0] <= 1'b0;
657			SZ_32B: rdack_subaddr[1:0] <= 2'b0;
658			SZ_BUS: rdack_subaddr[WBLSB-1:0] <= {(WBLSB){1'b0}};
659			endcase
660			// Verilator lint_on  WIDTH
661		end
662		// }}}
663	
664		// rdack_len
665		// {{{
666		// Total length remaining, from the perspective of the bus return.
667		// Hence, on any bus return, we drop by the number of bytes valid
668		// in that return, or minus rdack_size.
669		always @(posedge i_clk)
670		if (!o_busy)
671		begin
672			if (!OPT_LOWPOWER || i_request)
673				rdack_len <= i_transferlen;
674		end else if (i_rd_ack)
675		begin
676			rdack_len <= rdack_len-{ {(LGLENGTH-WBLSB){1'b0}}, rdack_size };
677			if (rdack_len <= { {(LGLENGTH-WBLSB){1'b0}}, rdack_size })
678				rdack_len <= 0;
679		end
680		// }}}
681	
682		// rdack_size
683		// {{{
684		always @(posedge i_clk)
685		if (!o_busy)
686		begin
687			if (!OPT_LOWPOWER || i_request)
688				rdack_size <= first_size;
689		end else if (i_rd_ack)
690		begin
691			case(r_size)
692			SZ_BYTE:rdack_size <= 1;
693			// Verilator lint_off WIDTH
694			SZ_16B: if (rdack_len > 2 + rdack_size)
695					rdack_size <= 2;
696				else
697					rdack_size <= rdack_len - rdack_size;
698			SZ_32B: if (rdack_len > 4 + rdack_size)
699					rdack_size <= 4;
700				else
701					rdack_size <= rdack_len - rdack_size;
702			SZ_BUS: if (rdack_len > DW/8 + rdack_size)
703					rdack_size <= DW/8;
704				else
705					rdack_size <= rdack_len - rdack_size;
706				// Verilator lint_on  WIDTH
707			endcase
708		end
709		// }}}
710	
711		// fill, next_fill (depends on rdack_size)
712		// {{{
713		always @(*)
714		begin
715			next_fill = (M_VALID) ? 0 : fill;
716			if (i_rd_ack)
717				next_fill = next_fill + { 1'b0, rdack_size };
718		end
719	
720		always @(posedge i_clk)
721		if (!o_busy)
722			fill <= 0;
723		else
724			fill <= next_fill;
725		// }}}
726	
727		// m_valid
728		// {{{
729		initial	m_valid = 0;
730		always @(posedge i_clk)
731		if (i_reset || !o_busy)
732			m_valid <= 1'b0;
733		else begin
734			m_valid <= 0;
735			if ((!m_valid || !m_last) && rdack_len == 0 && fill > 0)
736				m_valid <= 1;
737			else if (o_rd_cyc && i_rd_ack)
738				m_valid <= 1'b1;
739		end
740		// }}}
741	
742		// sreg
743		// {{{
744		initial	pre_shift = 0;
745		always @(posedge i_clk)
746		if (!o_busy)
747		begin
748			pre_shift <= 0;
749			if (!OPT_LOWPOWER || i_request)
750				pre_shift <= i_addr[WBLSB-1:0];
751		end else if (o_rd_cyc && i_rd_ack)
752		begin
753			case(r_size)
754			SZ_BYTE: pre_shift <= pre_shift + (r_inc ? 1 : 0);
755			SZ_16B:  begin
756				// {{{
757				pre_shift <= pre_shift + (r_inc ? 2 : 0);
758				pre_shift[0] <= 1'b0;
759				end
760				// }}}
761			SZ_32B:  begin
762				// {{{
763				// Verilator lint_off WIDTH
764				pre_shift <= pre_shift + (r_inc ? 4 : 0);
765				// Verilator lint_on  WIDTH
766				pre_shift[1:0] <= 2'b0;
767				end
768				// }}}
769			SZ_BUS:  pre_shift <= 0;
770			endcase
771		end
772	
773		always @(*)
774		if (OPT_LITTLE_ENDIAN)
775			pre_shifted_data = i_rd_data >> (8*pre_shift);
776		else
777			pre_shifted_data = i_rd_data << (8*pre_shift);
778	
779		initial	sreg = 0;
780		always @(posedge i_clk)
781		if (!o_busy)
782			sreg <= 0;
783		else if (o_rd_cyc && i_rd_ack)
784		begin
785			// {{{
786			// Verilator lint_off WIDTH
787			sreg <= pre_shifted_data;
788			// Verilator lint_on  WIDTH
789			// }}}
790		end else if (m_valid)
791		begin
792			// {{{
793			sreg <= {(DW){1'b0}};
794			// }}}
795		end
796		// }}}
797	
798		// m_bytes
799		// {{{
800		initial	m_bytes = 0;
801		always @(posedge i_clk)
802		if (!o_busy)
803		begin
804			m_bytes <= 0;
805		end else if (i_rd_ack)
806		begin
807			if (|next_fill[WBLSB+1:WBLSB]) // if next_fill >= DW/8)
808				// Verilator lint_off WIDTH
809				m_bytes <= DW/8;
810				// Verilator lint_on  WIDTH
811			else
812				m_bytes <= { 1'b0, next_fill[WBLSB-1:0] };
813		end else if (rdack_len == 0)
814			m_bytes <= next_fill[WBLSB:0];
815		// }}}
816	
817		// m_last
818		// {{{
819		always @(*)
820		begin
821			last_request_addr = i_addr;
822			if (r_inc)
823				// Verilator lint_off WIDTH
824				last_request_addr = i_addr + i_transferlen - 1;
825				// Verilator lint_on  WIDTH
826		end
827	
828		initial	m_last = 0;
829		always @(posedge i_clk)
830		if (i_reset)
831			m_last <= 1'b0;
832		else if (!o_busy)
833		begin
834			m_last <= 1'b0;
835			if (!OPT_LOWPOWER || i_request)
836			case(i_size)
837			SZ_BYTE: m_last <= (i_transferlen <= 1);
838			SZ_16B: m_last <= (last_request_addr[ADDRESS_WIDTH-1:1] != i_addr[ADDRESS_WIDTH-1:1]);
839			SZ_32B: m_last <= (last_request_addr[ADDRESS_WIDTH-1:2] != i_addr[ADDRESS_WIDTH-1:2]);
840			SZ_BUS: m_last <= (last_request_addr[ADDRESS_WIDTH-1:WBLSB] != i_addr[ADDRESS_WIDTH-1:WBLSB]);
841			endcase
842		end else if (i_rd_ack)
843		begin
844			// Verilator lint_off WIDTH
845			m_last <= (rdack_len <= rdack_size) && (next_fill <= DW/8);
846			// Verilator lint_on  WIDTH
847		end else if (rdack_len == 0)
848			m_last <= 1;
849		// }}}
850	
851		assign	M_VALID = m_valid;
852		assign	M_DATA = sreg;
853		assign	M_BYTES= m_bytes;
854		assign	M_LAST = m_last;
855	
856		// Keep Verilator happy
857		// {{{
858		// Verilator coverage_off
859		// Verilator lint_off UNUSED
860		wire	unused;
861		assign	unused = &{ 1'b0, M_READY, last_request_addr[0],
862					r_addr[ADDRESS_WIDTH-1:WBLSB] };
863		// Verilator lint_on  UNUSED
864		// Verilator coverage_on
865		// }}}
