948		//
949	
950		always @(*)
951			f_stb_first = (rdstb_len == f_cfg_len);
952	
953		always @(*)
954		if (rdstb_len == 0)
955			f_stb_last <= 1'b0;
956		else case(r_size)
957		SZ_BYTE: f_stb_last <= (rdstb_len == 1);
