972		SZ_32B:  f_ack_last <= (rdack_len + f_excess_last_return[1:0] == 4);
973		SZ_BUS:  f_ack_last <= (rdack_len + f_excess_last_return[WBLSB-1:0] == DW/8);
974		endcase
975		// }}}
