977		//
978		// f_excess_last_return
979		// {{{
980		////////////////////////////////////////////////////////////////////////
981		//
982		//
983	
984		always @(*)
985		begin
986			f_excess_last_return = f_cfg_addr + f_cfg_len;
987			case(r_size)
988			SZ_BYTE: f_excess_last_return = 0;
989			SZ_16B:  begin
990				f_excess_last_return = 2 - f_excess_last_return[0];
991				f_excess_last_return[WBLSB-1:1] = 0;
992				end
993			SZ_32B:  begin
994				f_excess_last_return = 4 - f_excess_last_return[1:0];
995				f_excess_last_return[WBLSB-1:2] = 0;
996				end
997			SZ_BUS:  f_excess_last_return = (DW/8) - f_excess_last_return[WBLSB-1:0];
998			endcase
999		end
