1001		////////////////////////////////////////////////////////////////////////
1002		//
1003		// first_size
1004		// {{{
1005		////////////////////////////////////////////////////////////////////////
1006		//
1007		//
1008	
1009		always @(*)
1010		if (!i_reset && o_busy && !o_err)
1011		begin
1012			case(r_size)
1013			SZ_BYTE: assert(first_size == 1);
1014			SZ_16B:  assert(first_size == (f_cfg_addr[0]) ? 1 : 2);
1015			SZ_32B:  assert(first_size == 4 - f_cfg_addr[1:0]);
1016			SZ_BUS:  assert(first_size == (DW/8) - f_cfg_addr[WBLSB-1:0]);
1017			endcase
1018	
1019			if (first_size > f_cfg_len)
1020				assert(first_size == f_cfg_len);
1021		end
