1033		begin
1034			if (!r_inc)
1035			begin
1036				assert({ o_rd_addr, subaddr } == f_cfg_addr);
1037			end else if (rdstb_len != 0)
1038				assert({ o_rd_addr, subaddr } == f_cfg_addr + f_rcvd + f_outstanding_bytes);
