1120				f_outstanding_bytes = wb_outstanding * (DW/8);
1121			else
1122				f_outstanding_bytes = wb_outstanding * (DW/8) - f_cfg_addr[WBLSB-1:0];
1123		endcase
1124	
1125		always @(*)
1126		if (!i_reset && o_busy && !o_err)
1127			assert(f_outstanding_bytes <= f_cfg_len + ((rdstb_len == 0) ? f_excess_last_return : 0));
1128		// }}}
1129		////////////////////////////////////////////////////////////////////////
1130		//
1131		// base_sel
1132		// {{{
1133		////////////////////////////////////////////////////////////////////////
1134		//
1135		//
1136	
1137		always @(posedge i_clk)
1138		if (!i_reset && $past(o_busy) && o_busy && !o_err)
1139			assert(base_sel != 0);
1140	
1141		always @(*)
1142		if (OPT_LITTLE_ENDIAN)
1143		begin
1144			case(r_size)
1145			SZ_BYTE: f_base_sel = { {(DW/8-1){1'b0}}, 1'h1 } << subaddr;
1146			SZ_16B:  f_base_sel = { {(DW/8-2){1'b0}}, 2'h3 } << { subaddr[WBLSB-1:1], 1'b0 };
1147			SZ_32B:  f_base_sel = { {(DW/8-4){1'b0}}, 4'hf } << { subaddr[WBLSB-1:1], 2'b00 };
1148			SZ_BUS: if (r_inc || (!r_inc && f_stb_first))
1149					f_base_sel = { (DW/8){1'b1} } << subaddr;
1150				else
1151					f_base_sel = { (DW/8){1'b1} };
1152			endcase
1153		end else begin
1154			case(r_size)
1155			SZ_BYTE: f_base_sel = { 1'h1, {(DW/8-1){1'b0}} } >> subaddr;
1156			SZ_16B:  f_base_sel = { 2'h3, {(DW/8-2){1'b0}} } >> { subaddr[WBLSB-1:1], 1'b0 };
1157			SZ_32B:  f_base_sel = { 4'hf, {(DW/8-4){1'b0}} } >> { subaddr[WBLSB-1:2], 2'b00 };
1158			SZ_BUS: if (r_inc || (!r_inc && f_stb_first))
1159					f_base_sel = { (DW/8){1'b1} } >> subaddr;
1160				else
1161					f_base_sel = { (DW/8){1'b1} };
1162			endcase
1163		end
1164	
1165		always @(posedge i_clk)
1166		if (!i_reset && $past(o_busy) && o_busy && !o_err && rdstb_len > 0)
1167		begin
1168			if (r_size == SZ_BUS)
1169			begin
1170				assert(base_sel == { (DW/8){1'b1} });
1171			end else begin
1172				assert(base_sel == f_base_sel);
1173			end
1174		end
1175		// }}}
1176		////////////////////////////////////////////////////////////////////////
1177		//
1178		// o_rd_sel
1179		// {{{
1180		////////////////////////////////////////////////////////////////////////
1181		//
1182		//
1183	
1184		always @(*)
1185		if (!i_reset && o_busy && !o_err)
1186		begin
1187			assert(fill < (DW/8) + (M_VALID ? DW/8 : 0));
1188			if (rdstb_len != 0 || rdstb_len != rdstb_size)
1189				assert(rdstb_size <= $countones(o_rd_sel));
1190	
1191			if (!r_inc)
1192			case(r_size)
1193			SZ_BYTE: assert(o_rd_sel == base_sel);
1194			SZ_16B:  assert(o_rd_sel == (f_cfg_len < 2) ? first_sel : base_sel);
1195			SZ_32B:  assert(o_rd_sel == (f_cfg_len < 4) ? first_sel : base_sel);
1196			SZ_BUS:  assert(o_rd_sel == (f_cfg_len < DW/8) ? first_sel : base_sel);
1197			endcase
1198		end
1199	
1200		always @(*)
1201		if (!i_reset && f_past_valid && o_rd_stb && r_inc && !f_stb_last)
1202		begin
1203			assert(o_rd_sel != 0);
1204	
1205			if (OPT_LITTLE_ENDIAN)
1206			begin
1207				case(r_size)
1208				SZ_BYTE:assert(o_rd_sel == { {(DW/8-1){1'b0}}, 1'b1 } << subaddr);
1209				SZ_16B: if (f_cfg_len < 2)
1210					begin
1211						if (i_addr[0])
1212						begin
1213							assert(o_rd_sel == { {(DW/8-2){1'b0}}, 2'b01 } << { subaddr[WBLSB-1:1], 1'b0 });
1214						end else begin
1215							assert(o_rd_sel == { {(DW/8-2){1'b0}}, 2'b10 } << { subaddr[WBLSB-1:1], 1'b0 });
1216						end
1217					end else if (i_addr[0])
1218					begin
1219						assert(o_rd_sel == { {(DW/8-2){1'b0}}, 2'b01 } << { subaddr[WBLSB-1:1], 1'b0 });
1220					end else begin
1221						assert(o_rd_sel == { {(DW/8-2){1'b0}}, 2'b11 } << { subaddr[WBLSB-1:1], 1'b0 });
1222					end
1223				SZ_32B: if (f_cfg_len < 4)
1224					begin
1225						assert(o_rd_sel == { {(DW/8-4){1'b0}}, (4'b1111 << (4 - f_cfg_len)) } << { subaddr[WBLSB-1:2], 2'b00 });
1226					end else begin
1227						assert(o_rd_sel == { {(DW/8-4){1'b0}}, 4'b1111 } << { subaddr[WBLSB-1:2], 2'b00 });
1228					end
1229				SZ_BUS: if (f_cfg_len < DW/8)
1230					begin
1231						assert(o_rd_sel == { (DW/8){1'b1} } << (DW/8 - f_cfg_len));
1232					end else if (rdstb_len == f_cfg_len)
1233					begin
1234						assert(o_rd_sel == { (DW/8){1'b1} } << subaddr);
1235					end else begin
1236							assert(o_rd_sel == { (DW/8){1'b1} });
1237					end
1238				endcase
1239			end else case(r_size)
1240			SZ_BYTE:assert(o_rd_sel == { 1'b1, {(DW/8-1){1'b0}} } >> subaddr);
1241			SZ_16B: if (f_cfg_len < 2)
1242				begin
1243					if (i_addr[0])
1244					begin
1245						assert(o_rd_sel == { 2'b01, {(DW/8-2){1'b0}} } >> { subaddr[WBLSB-1:1], 1'b0 });
1246					end else begin
1247						assert(o_rd_sel == { 2'b10, {(DW/8-2){1'b0}} } >> { subaddr[WBLSB-1:1], 1'b0 });
1248					end
1249				end else if (subaddr[0])
1250				begin
1251					assert(o_rd_sel == { 2'b01, {(DW/8-2){1'b0}} } >> { subaddr[WBLSB-1:1], 1'b0 });
1252				end else begin
1253					assert(o_rd_sel == { 2'b11, {(DW/8-2){1'b0}} } >> { subaddr[WBLSB-1:1], 1'b0 });
1254				end
1255			SZ_32B: if (f_cfg_len < 4)
1256				begin
1257					if (i_addr[1:0] == 2'b00)
1258					begin
1259						assert(o_rd_sel == {(4'b1111 >> (4 - f_cfg_len)), {(DW/8-4){1'b0}} }
1260							>> { subaddr[WBLSB-1:2], 2'b00 });
1261					end else if (f_cfg_len[1:0] < (4 - subaddr[1:0]))
1262					begin
1263						assert(o_rd_sel == {(4'b1111 >> (4 - f_cfg_len)), {(DW/8-4){1'b0}} }
1264							>> { subaddr[WBLSB-1:2], 2'b00 });
1265					end else begin
1266						assert(o_rd_sel == {(4'b1111 >> (subaddr[1:0])), {(DW/8-4){1'b0}} }
1267							>> { subaddr[WBLSB-1:2], 2'b00 });
1268					end
1269				end else if (subaddr[1:0] == 2'b00)
1270				begin
1271					assert(o_rd_sel == { 4'b1111, {(DW/8-4){1'b0}} } >> { subaddr[WBLSB-1:2], 2'b00 });
1272				end else begin
1273					assert(o_rd_sel == { (4'b1111 >> subaddr[1:0]), {(DW/8-4){1'b0}} } >> { subaddr[WBLSB-1:2], 2'b00 });
1274				end
1275			SZ_BUS: if (f_cfg_len < DW/8)
1276				begin
1277					if (i_addr[WBLSB-1:0] == 0)
1278					begin
1279						assert(o_rd_sel == { (DW/8){1'b1} } >> (DW/8 - f_cfg_len - subaddr));
1280					end else if (f_cfg_len[WBLSB-1:0] < (DW/8 - subaddr))
1281					begin
1282						assert(o_rd_sel == { (DW/8){1'b1} } >> (DW/8 - f_cfg_len));
1283					end else begin
1284						assert(o_rd_sel == { (DW/8){1'b1} } >> (subaddr));
1285					end
1286				end else if (f_stb_first)
1287				begin
1288					assert(o_rd_sel == { (DW/8){1'b1} } >> subaddr);
1289				end else begin
1290					assert(o_rd_sel == { (DW/8){1'b1} });
1291				end
1292			endcase
1293		end
1294	
1295		// }}}
1296		////////////////////////////////////////////////////////////////////////
1297		//
1298		// rdstb_size
1299		// {{{
1300		////////////////////////////////////////////////////////////////////////
1301		//
1302		//
1303	
1304		always @(*)
1305		begin
1306			case(r_size)
1307			SZ_BYTE: f_stb_size = 1;
1308			SZ_16B:  f_stb_size = 2;
1309			SZ_32B:  f_stb_size = 4;
1310			SZ_BUS:  f_stb_size = DW/8;
1311			endcase
1312	
1313			if (rdstb_len == f_cfg_len)
1314			case(r_size)
1315			SZ_BYTE: f_stb_size =  1;
1316			SZ_16B:  f_stb_size = (2 - r_addr[  0]);
1317			SZ_32B:  f_stb_size = (4 - r_addr[1:0]);
1318			SZ_BUS:  f_stb_size = (DW/8 - r_addr[WBLSB-1:0]);
1319			endcase
1320		end
1321	
1322		always @(*)
1323		if (!i_reset && o_busy && !o_err && o_rd_cyc && o_rd_stb)
1324		begin
1325			if (f_stb_first && f_stb_last)
1326			begin	// means that packet is one word only
1327				assert(rdstb_size == f_cfg_len);
1328			end else if (f_stb_last)
1329			begin
1330				assert(rdstb_size == rdstb_len);
1331			end else begin
1332				assert(rdstb_size == f_stb_size);
1333			end
1334		end
1335	
1336		always @(*)
1337		if(!i_reset && o_busy && !o_err && rdstb_len > 0)
1338			assert(rdstb_size <= rdstb_len);
1339		// }}}
1340		////////////////////////////////////////////////////////////////////////
1341		//
1342		// rdack_size
1343		// {{{
1344		////////////////////////////////////////////////////////////////////////
1345		//
1346		//
1347	
1348		always @(*)
1349		begin
1350			case(r_size)
1351			SZ_BYTE: f_ack_size = 1;
1352			SZ_16B:  f_ack_size = 2;
1353			SZ_32B:  f_ack_size = 4;
1354			SZ_BUS:  f_ack_size = DW/8;
1355			endcase
1356	
1357			if (f_rcvd == 0)
1358			case(r_size)
1359			SZ_BYTE: f_ack_size =  1;
1360			SZ_16B:  f_ack_size = (2 - r_addr[  0]);
1361			SZ_32B:  f_ack_size = (4 - r_addr[1:0]);
1362			SZ_BUS:  f_ack_size = (DW/8 - r_addr[WBLSB-1:0]);
1363			endcase
1364	
1365			if (f_rcvd + f_ack_size > r_transferlen)
1366				f_ack_size = r_transferlen - f_rcvd;
1367		end
1368	
1369		always @(*)
1370		if (!i_reset && o_busy && !o_err && o_rd_cyc)
1371		begin
1372			if (f_ack_first && f_ack_last)
1373			begin	// means that packet is one word only
1374				assert(rdack_size == f_cfg_len);
1375			end else if (f_ack_last)
1376			begin
1377				assert(rdack_size == rdack_len);
1378			end else begin
1379				assert(rdack_size == f_ack_size);
1380			end
1381		end
1382		// }}}
1383		////////////////////////////////////////////////////////////////////////
1384		//
1385		// rdstb_len, rdack_len
1386		// {{{
1387		////////////////////////////////////////////////////////////////////////
1388		//
1389		//
1390	
1391		always @(*)
1392		if (!i_reset && o_busy && !o_err && o_rd_cyc)
1393		begin
1394			if (!f_stb_first)
1395			begin
1396				case(r_size)	// Check the rdstb_len whether is odd or even
1397				SZ_16B: if (f_cfg_len > 2 && rdstb_len != 0)
1398					begin
1399						assert(rdstb_len[0] == (f_cfg_addr[0] ^ f_cfg_len[0]));
1400					end
1401				SZ_32B: if (f_cfg_len > 4 && rdstb_len != 0)
1402					begin
1403						lower_len_bits = f_cfg_len - (4 - f_cfg_addr[1:0]);
1404						assert(rdstb_len[1:0] == ((f_cfg_addr[1:0] == 2'b00) ? f_cfg_len[1:0] : lower_len_bits[1:0]));
1405					end
1406				SZ_BUS: if (f_cfg_len > DW/8 && rdstb_len != 0)
1407					begin
1408						lower_len_bits = f_cfg_len - (DW/8 - f_cfg_addr[WBLSB-1:0]);
1409						assert(rdstb_len[WBLSB-1:0] == ((f_cfg_addr[WBLSB-1:0] == 0) ? f_cfg_len[WBLSB-1:0] : lower_len_bits[WBLSB-1:0]));
1410					end
1411				endcase
1412	
1413				if (f_stb_last)
1414				begin
1415					case(r_size)
1416					SZ_BYTE: assert(rdstb_len == 1);
1417					SZ_16B:  assert(rdstb_len == 2 - f_excess_last_return[0]);
1418					SZ_32B:  assert(rdstb_len == 4 - f_excess_last_return[1:0]);
1419					SZ_BUS:  assert(rdstb_len == (DW/8) - f_excess_last_return[WBLSB-1:0]);
1420					endcase
1421				end
1422	
1423				if (!f_ack_first)
1424				begin
1425					if (r_size != 2'b11)
1426					begin
1427						assert(rdack_len[0] == (f_cfg_addr[0] ^ f_cfg_len[0]));
1428					end
1429	
1430					if (f_ack_last)
1431					begin
1432						case(r_size)
1433						SZ_BYTE: assert(rdack_len == 1);
1434						SZ_16B:  assert(rdack_len == 2 - f_excess_last_return[0]);
1435						SZ_32B:  assert(rdack_len == 4 - f_excess_last_return[1:0]);
1436						SZ_BUS:  assert(rdack_len == (DW/8) - f_excess_last_return[WBLSB-1:0]);
1437						endcase
1438					end
1439				end
1440			end
1441		end
1442	
1443		always @(*)
1444		if(!i_reset && o_busy && !o_err && !f_ack_first)
1445		begin
1446			assert(f_rcvd <= f_cfg_len + DW/8 - 1);
1447			if(rdstb_len != 0)
1448				assert(f_cfg_len == f_rcvd + f_outstanding_bytes + rdstb_len);
1449		end
1450	
1451		always @(*)
1452		if(!i_reset && o_busy && !o_err)
1453		begin
1454			assert(rdack_len <= f_cfg_len);
1455			assert(rdstb_len <= rdack_len);
1456			if(rdstb_len != 0)
1457			begin
1458				assert(rdack_len == rdstb_len + f_outstanding_bytes);
1459			end else begin
1460				assert(f_outstanding_bytes == rdack_len
1461					+ ((rdstb_len == 0 && rdack_len != 0)
1462						? f_excess_last_return : 0));
1463			end
1464		end
1465	
1466		always @(*)
1467		if(!i_reset && o_busy && !o_err)
1468			assert(rdstb_len != 0 || !o_rd_stb);
1469		// }}}
