1471		//
1472		// f_rcvd
1473		// {{{
1474		////////////////////////////////////////////////////////////////////////
1475		//
1476		//
1477	
1478		initial	f_rcvd = 0;
1479		always @(posedge i_clk)
1480		if (i_reset || !o_busy || (o_rd_cyc && i_rd_err))
1481			f_rcvd <= 0;
1482		else if (o_rd_cyc && i_rd_ack)
1483		begin
1484			if (f_rcvd == 0)
1485			begin
1486				case(r_size)
1487				SZ_BYTE: f_rcvd <= f_rcvd + 1;
1488				SZ_16B:  f_rcvd <= f_rcvd + (f_cfg_len < 2) ? 1 : (2 - f_cfg_addr[0]);
1489				SZ_32B:  f_rcvd <= f_rcvd + (f_cfg_len < (4 - f_cfg_addr[1:0])) ? f_cfg_len : (4 - f_cfg_addr[1:0]);
1490				SZ_BUS:  f_rcvd <= f_rcvd + (f_cfg_len < (DW/8 - f_cfg_addr[WBLSB-1:0])) ? f_cfg_len : (DW/8 - f_cfg_addr[WBLSB-1:0]);
1491				endcase
1492			end else if (f_ack_last)
1493			begin
1494				case(r_size)
1495				SZ_BYTE: f_rcvd <= f_rcvd + 1;
1496				SZ_16B:  f_rcvd <= f_rcvd + (2 - f_excess_last_return[0]);
1497				SZ_32B:  f_rcvd <= f_rcvd + (4 - f_excess_last_return[1:0]);
1498				SZ_BUS:  f_rcvd <= f_rcvd + (DW/8 - f_excess_last_return[WBLSB-1:0]);
1499				endcase
1500			end else
1501			begin
1502				case(r_size)
1503				SZ_BYTE: f_rcvd <= f_rcvd + 1;
1504				SZ_16B:  f_rcvd <= f_rcvd + 2;
1505				SZ_32B:  f_rcvd <= f_rcvd + 4;
1506				SZ_BUS:  f_rcvd <= f_rcvd + DW/8;
1507				endcase
1508			end
1509		end
1510	
1511		always @(*)
1512		if (!i_reset && o_busy && !o_err && rdack_len != 0)
1513			assert(f_rcvd == f_cfg_len - rdack_len);
1514		// }}}
