1516		//
1517		// Outgoing stream properties
1518		// {{{
1519		////////////////////////////////////////////////////////////////////////
1520		//
1521		//
1522	
1523		always @(posedge i_clk)
1524		if (!f_past_valid || $past(i_reset))
1525			assert(!M_VALID);
1526	
1527		always @(*)
1528		if (!i_reset && o_busy && !o_err && !M_VALID)
1529			assert(fill == 0);
