1536	
1537			if (M_LAST)
1538				assert(!o_rd_stb);
1539		end
1540	
1541		always @(*)
1542		if (!i_reset && o_busy)
1543			assert(f_sent <= r_transferlen);
1544	
1545		always @(*)
1546		if (!i_reset && o_busy)
1547		begin
1548			if (!M_VALID)
1549			begin
1550				assert(f_rcvd == f_sent);
1551			end else
1552				assert(f_rcvd == f_sent + M_BYTES);
1553		end
1554	
1555		always @(*)
1556		if (!i_reset && o_busy && !o_rd_stb && !o_err)
1557			assert(rdstb_len == 0);
1558	
1559		initial	f_sent = 0;
1560		always @(posedge i_clk)
1561		if (i_reset || !o_busy || (o_rd_cyc && i_rd_err))
1562			f_sent <= 0;
1563		else if (M_VALID && M_READY)
1564		begin
1565			if (M_LAST)
