1567			else
1568				f_sent <= f_sent + M_BYTES;
1569		end
1570		// }}}
1571		////////////////////////////////////////////////////////////////////////
1572		//
1573		// "Contract" properties
1574		// {{{
1575		////////////////////////////////////////////////////////////////////////
1576		//
1577		//
1578	// `define	CONTRACT
1579	`ifdef CONTRACT
1580		(* anyconst *)	reg			fc_check;
1581		(* anyconst *)	reg	[F_LGCOUNT-1:0]	fc_posn;
1582		(* anyconst *)	reg	[7:0]		fc_byte;
1583	
1584			wire			fwb_check,   fm_check;
1585		(* keep *) reg [WBLSB-1:0]	fwb_shift,   fm_shift;
1586		(* keep *) reg [DW-1:0]		fwb_shifted, fm_shifted;
1587	
1588		// Assume a known response from the bus
1589		// {{{
1590		assign	fwb_check = fc_check && (o_rd_cyc && i_rd_ack)
1591					&& (f_rcvd <= fc_posn)
1592					&& (fc_posn < f_rcvd + f_ack_size);
1593	
1594		always @(*)
1595		if (!i_reset && o_busy && !o_err && rdstb_len != f_cfg_len
