1597			assert(pre_shift == r_addr[WBLSB-1:0]);
1598	
1599		always @(*)
1600		begin
1601			fwb_shift = fc_posn - f_rcvd;
1602			fwb_shift = fwb_shift + pre_shift;
1603		end
1604	
1605		always @(*)
1606		if (OPT_LITTLE_ENDIAN)
1607			fwb_shifted = i_rd_data >> (8*fwb_shift);
1608		else
1609			fwb_shifted = i_rd_data << (8*fwb_shift);
1610	
1611		always @(*)
1612		if (!i_reset && fwb_check)
1613		begin
1614			if (OPT_LITTLE_ENDIAN)
1615			begin
1616				assume(fwb_shifted[7:0] == fc_byte);
1617			end else begin
1618				assume(fwb_shifted[DW-1:DW-8] == fc_byte);
1619			end
1620		end
1621		// }}}
1622	
1623		// Assert a specific output
1624		// {{{
1625		assign	fm_check = fc_check && M_VALID
1626					&& (f_sent <= fc_posn)
1627					&& (fc_posn < f_sent + fill);
1628	
1629		always @(*)
1630			fm_shift = fc_posn - f_sent;
1631	
1632		always @(*)
1633		if (OPT_LITTLE_ENDIAN)
1634			fm_shifted = sreg >> (8*fm_shift);
1635		else
1636			fm_shifted = sreg << (8*fm_shift);
1637	
1638		always @(*)
1639		if (!i_reset && fm_check)
1640		begin
1641			if (OPT_LITTLE_ENDIAN)
1642			begin
1643				assert(fm_shifted[7:0] == fc_byte);
1644			end else begin
1645				assert(fm_shifted[DW-1:DW-8] == fc_byte);
1646			end
1647		end
1648		// }}}
1649	`endif	// CONTRACT
1650	
1651		// }}}
