1653		//
1654		// Cover properties
1655		// {{{
1656		////////////////////////////////////////////////////////////////////////
1657		//
1658		//
1659	
1660		always @(*)
1661		begin
1662			cover(!i_reset && i_request);
1663			cover(o_busy);
1664			cover(o_rd_cyc);
1665			cover(o_rd_cyc && i_rd_ack);
1666		end
1667	
1668	`ifdef CONTRACT
1669		always @(*)
1670			cover(!i_reset && fm_check);
1671	`endif
1672	
1673		// }}}
1674		////////////////////////////////////////////////////////////////////////
1675		//
1676		// "Careless" assumptions
1677		// {{{
1678		////////////////////////////////////////////////////////////////////////
1679		//
1680		//
1681	
1682		// The outgoing stream isn't quite an AXI stream master interface,
1683		// since WB doesn't have backpressure.  Therefore, we assume M_READY
1684		// is always high when we need it to be.
1685	
1686		always @(*)
1687		if (!OPT_FIRSTBEAT_TRIM)
1688		case(f_cfg_size)
1689		SZ_16B: assume(f_cfg_len + f_cfg_addr[0] >= 2);
1690		SZ_32B: assume(f_cfg_len + f_cfg_addr[1:0] >= 4);
1691		SZ_BUS: assume(f_cfg_len + f_cfg_addr[WBLSB-1:0] >= BUS_WIDTH/8);
1692		endcase
1693	
1694		always @(*)
1695		if (!i_reset && M_VALID)
1696			assume(M_READY);
1697	
1698		always @(*)
1699		if (!i_reset && o_busy && !o_err)
1700			assume(r_transferlen + f_cfg_addr < (1 << ADDRESS_WIDTH));
1701		// }}}
1702	`endif
1703	// }}}
1704	endmodule
1705

