48			parameter [0:0]	OPT_LITTLE_ENDIAN = 1'b0,
49			parameter	LGPIPE = 10,
50			// Abbreviations
51			localparam	DW = BUS_WIDTH,
52			localparam	AW = ADDRESS_WIDTH-$clog2(DW/8)
53			// }}}
54		) (
55			// {{{
56			input	wire	i_clk, i_reset,
57			// Configuration
58			// {{{
59			input	wire			i_request,
