76			// {{{
77			output	reg			o_wr_cyc, o_wr_stb,
78			output	wire			o_wr_we,
79			output	reg	[AW-1:0]	o_wr_addr,
80			output	reg	[DW-1:0]	o_wr_data,
81			output	reg	[DW/8-1:0]	o_wr_sel,
82			input	wire			i_wr_stall,
83			input	wire			i_wr_ack,
84			// Verilator coverage_off
85			input	wire	[DW-1:0]	i_wr_data,	// UNUSED
86			input	wire			i_wr_err
87			// Verilator coverage_on
88			// }}}
89			// }}}
90		);
