102		reg	[1:0]			r_size;
103		//
104		reg	[ADDRESS_WIDTH:0]	next_addr;
105		reg	[WBLSB-1:0]		subaddr;
106		reg	[2*DW-1:0]		next_data;
107		reg	[DW-1:0]		r_data;
108		reg	[2*DW/8-1:0]		next_sel, pre_sel;
109		reg	[DW/8-1:0]		r_sel;
