1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/zipdma/zipdma_ctrl.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	ZipDMA -- Simply handles the control requests for the ZipDMA.
8	//		Status reads and control writes using a 32-bit Wishbone bus
9	//	interface are handled here.
10	//
11	// Creator:	Dan Gisselquist, Ph.D.
12	//		Gisselquist Technology, LLC
13	//
14	////////////////////////////////////////////////////////////////////////////////
15	// }}}
16	// Copyright (C) 2022-2025, Gisselquist Technology, LLC
17	// {{{
18	// This program is free software (firmware): you can redistribute it and/or
19	// modify it under the terms of the GNU General Public License as published
20	// by the Free Software Foundation, either version 3 of the License, or (at
21	// your option) any later version.
22	//
23	// This program is distributed in the hope that it will be useful, but WITHOUT
24	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
25	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
26	// for more details.
27	//
28	// You should have received a copy of the GNU General Public License along
29	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
30	// target there if the PDF file isn't present.)  If not, see
31	// <http://www.gnu.org/licenses/> for a copy.
32	// }}}
33	// License:	GPL, v3, as defined and found on www.gnu.org,
34	// {{{
35	//		http://www.gnu.org/licenses/gpl.html
36	//
37	////////////////////////////////////////////////////////////////////////////////
38	//
39	`default_nettype none
40	// }}}
41	module zipdma_ctrl #(
42			// {{{
43			parameter	ADDRESS_WIDTH=30, LGMEMLEN = 10,
44			parameter	SLV_WIDTH=32,
45					// BUS_WIDTH=512,
46			parameter	LGDMALENGTH = ADDRESS_WIDTH,
47			parameter	ABORT_KEY = 32'h41425254,
48			parameter [0:0]	OPT_LOWPOWER = 1'b0,
49					// == { 8'd65, 8'd66, 8'd82, 8'd84 }, "ABRT",
50			localparam	AW = ADDRESS_WIDTH
51			// }}}
52		) (
53			// {{{
54			input	wire				i_clk, i_reset,
55			// Slave / control port
56			// {{{
57			input	wire				i_cyc, i_stb, i_we,
58			input	wire	[1:0]			i_addr,
59			input	wire	[SLV_WIDTH-1:0]		i_data,
60			input	wire [SLV_WIDTH/8-1:0]		i_sel,
61			//
62			// Verilator coverage_off
63			output	wire				o_stall,
64			// Verilator coverage_on
65			output	reg				o_ack,
66			output	reg	[SLV_WIDTH-1:0]		o_data,
67			// }}}
68			// DMA control wires and feedback
69			// {{{
70			output	reg				o_dma_request,
71			output	reg				o_dma_abort,
72			input	wire				i_dma_busy, i_dma_err,
73			output	reg	[AW-1:0]		o_src_addr,
74			output	reg	[AW-1:0]		o_dst_addr,
75			output	reg	[LGDMALENGTH-1:0]	o_length,
76			output	reg	[LGMEMLEN:0]		o_transferlen,
77			output	reg				o_mm2s_inc, o_s2mm_inc,
78			output	reg	[1:0]			o_mm2s_size,o_s2mm_size,
79			//
80			output	reg				o_trigger,
81			//
82			input	wire	[AW-1:0]		i_current_src,
83			input	wire	[AW-1:0]		i_current_dst,
84			input	wire	[LGDMALENGTH-1:0]	i_remaining_len,
85			// }}}
86			input	wire	[31:0]	i_dma_int,
87			output	reg		o_interrupt
88			// }}}
89		);
90	
91		// Local declarations
92		// {{{
93		reg		int_trigger, r_err, r_zero_len, r_busy;
94		reg	[4:0]	int_sel;
95		reg	[SLV_WIDTH-1:0]	next_src, next_dst, next_len, next_tlen,
96				w_control_reg;
97		// }}}
98	
99		// o_ack
100		// {{{
101		initial	o_ack = 1'b0;
102		always @(posedge i_clk)
103		if (i_reset)
104			o_ack <= 1'b0;
105		else
106			o_ack <= i_stb;
107		// }}}
108	
109		assign	o_stall = 1'b0;
110	
111		// w_control_reg
112		// {{{
113		always @(*)
114		begin
115			w_control_reg = 0;
116			w_control_reg[31]    = i_dma_busy;
117			w_control_reg[30]    = r_err || i_dma_err;
118			w_control_reg[29]    = int_trigger;
119			w_control_reg[28:24] = int_sel;
120			//
121			w_control_reg[LGMEMLEN:0] = o_transferlen;
122			//
123			w_control_reg[22]    = !o_s2mm_inc;
124			w_control_reg[21:20] =  o_s2mm_size;
125			//
126			w_control_reg[18]    = !o_mm2s_inc;
127			w_control_reg[17:16] =  o_mm2s_size;
128		end
129		// }}}
130	
131		// o_data
132		// {{{
133		always @(posedge i_clk)
134		if (!OPT_LOWPOWER || (i_stb && !o_stall && !i_we))
135		begin
136			o_data <= 0;
137			case(i_addr)
138			2'b00: o_data <= w_control_reg;
139			2'b01: o_data[AW-1:0] <= (i_dma_busy) ? i_current_src : o_src_addr;
140			2'b10: o_data[AW-1:0] <= (i_dma_busy) ? i_current_dst : o_dst_addr;
141			2'b11: o_data[LGDMALENGTH-1:0] <= (i_dma_busy) ? i_remaining_len : o_length;
142			endcase
143		end
144		// }}}
145	
146		// o_trigger
147		// {{{
148		always @(posedge i_clk)
149		if (i_reset || o_dma_abort || i_dma_err || !i_dma_busy)
150			o_trigger <= 1'b0;
151		else if (!int_trigger)
152			o_trigger <= 1'b1;
153		else
154			o_trigger <= i_dma_int[int_sel];
155		// }}}
156	
157		// next_src
158		// {{{
159		always @(*)
160		begin
161			next_src = 32'h00;
162			next_src[AW-1:0] = o_src_addr;
163	
164			if (i_sel[0]) next_src[ 7: 0] = i_data[ 7: 0];
165			if (i_sel[1]) next_src[15: 8] = i_data[15: 8];
166			if (i_sel[2]) next_src[23:16] = i_data[23:16];
167			if (i_sel[3]) next_src[31:24] = i_data[31:24];
168		end
169		// }}}
170	
171		// next_dst
172		// {{{
173		always @(*)
174		begin
175			next_dst = 32'h00;
176			next_dst[AW-1:0] = o_dst_addr;
177	
178			if (i_sel[0]) next_dst[ 7: 0] = i_data[ 7: 0];
179			if (i_sel[1]) next_dst[15: 8] = i_data[15: 8];
180			if (i_sel[2]) next_dst[23:16] = i_data[23:16];
181			if (i_sel[3]) next_dst[31:24] = i_data[31:24];
182		end
183		// }}}
184	
185		// next_len
186		// {{{
187		always @(*)
188		begin
189			next_len = 32'h00;
190			next_len[LGDMALENGTH-1:0] = o_length;
191	
192			if (i_sel[0]) next_len[ 7: 0] = i_data[ 7: 0];
193			if (i_sel[1]) next_len[15: 8] = i_data[15: 8];
194			if (i_sel[2]) next_len[23:16] = i_data[23:16];
195			if (i_sel[3]) next_len[31:24] = i_data[31:24];
196		end
197		// }}}
198	
199		// next_tlen
200		// {{{
201		always @(*)
202		begin
203			next_tlen = 32'h00;
204			next_tlen[LGMEMLEN-1:0] = o_transferlen[LGMEMLEN-1:0];
205	
206			if (i_sel[0]) next_tlen[ 7: 0] = i_data[ 7: 0];
207			if (i_sel[1]) next_tlen[15: 8] = i_data[15: 8];
208			if (i_sel[2]) next_tlen[23:16] = i_data[23:16];
209			if (i_sel[3]) next_tlen[31:24] = i_data[31:24];
210	
211			next_tlen[SLV_WIDTH-1:LGMEMLEN] = 0;
212			next_tlen[LGMEMLEN] = (next_tlen[LGMEMLEN-1:0] == 0);
213		end
214		// }}}
215	
216		// Process i_data writes
217		// {{{
218		always @(posedge i_clk)
219		if (i_reset)
220		begin
221			// {{{
222			o_src_addr    <= {(AW){1'b0}};
223			o_dst_addr    <= {(AW){1'b0}};
224			o_length      <= {(LGDMALENGTH){1'b0}};
225			r_zero_len    <= 1'b1;
226			o_transferlen <= { 1'b1, {(LGMEMLEN){1'b0}} };
227	
228			o_s2mm_inc    <= 1'b0;
229			o_s2mm_size   <= 2'b0;
230	
231			o_mm2s_inc  <= 1'b0;
232			o_mm2s_size <= 2'b0;
233	
234			int_trigger <= 1'b0;
235			int_sel     <= 5'h0;
236			// }}}
237		end else if (i_stb && !o_stall && i_we && !o_dma_request && !i_dma_busy)
238		begin // Register write, DMA is idle
239			// {{{
240			case(i_addr)
241			2'b00: begin // Control registers
242				// {{{
243				o_transferlen[LGMEMLEN:0] <= next_tlen[LGMEMLEN:0];
244				if (i_sel[2])
245				begin
246					o_s2mm_inc  <= !i_data[22];
247					o_s2mm_size <=  i_data[21:20];
248					//
249					o_mm2s_inc  <= !i_data[18];
250					o_mm2s_size <=  i_data[17:16];
251				end
252	
253				if (i_sel[3])
254				begin
255					int_trigger <= i_data[29];
256					int_sel     <= i_data[28:24];
257				end end
258				// }}}
259			2'b01: o_src_addr <= next_src[AW-1:0];
260			2'b10: o_dst_addr <= next_dst[AW-1:0];
261			2'b11: begin // o_length
262				// {{{
263				o_length <= next_len[LGDMALENGTH-1:0];
264				r_zero_len <= (next_len[LGDMALENGTH-1:0] == 0);
265				end
266				// }}}
267			endcase
268			// }}}
269		end else if (i_dma_busy)
270		begin
271			o_src_addr <= i_current_src;
272			o_dst_addr <= i_current_dst;
273		end
274		// }}}
275	
276		// o_dma_request, o_dma_abort, o_interrupt, r_err
277		// {{{
278		always @(posedge i_clk)
279		if (i_reset)
280		begin
281			// {{{
282			o_dma_request <= 1'b0;
283			o_dma_abort   <= 1'b0;
284	
285			r_err <= 1'b0;
286	
287			o_interrupt <= 1'b0;
288			// }}}
289		end else begin
290			r_busy <= i_dma_busy;
291	
292			if (!i_dma_busy)
293			begin
294				o_dma_request <= 1'b0;
295				o_dma_abort   <= 1'b0;
296			end
297	
298			if (i_dma_err)
299				r_err <= 1'b1;
300			if (r_busy && (!i_dma_busy || i_dma_err))
301				o_interrupt <= 1'b1;
302	
303			if (i_stb && !o_stall && i_we && i_addr == 2'b00)
304			begin
305			// {{{
306				if (o_dma_request || i_dma_busy)
307				begin
308					// Deal with abort requests
309					if ((&i_sel) && i_data == ABORT_KEY)
310						{ o_dma_request, o_dma_abort } <= 2'b01;
311	
312				end else if (i_sel[3])
313				begin
314					// Clear interrupts, errors, and potentially
315					// restart the DMA
316					if (i_data[29] || !i_data[30])
317						o_interrupt <= 1'b0;
318					if (i_data[30])
319						r_err <= 1'b0;
320					if (!i_data[31] && (!r_err || i_data[30]))
321						o_dma_request <= !r_zero_len;
322				end
323			// }}}
324			end
325		end
326		// }}}
327	
328		// Keep Verilator happy
329		// {{{
330		// Verilator coverage_off
331		// Verilator lint_off UNUSED
332		wire	unused;
333		assign	unused = &{ 1'b0, i_cyc, next_tlen[SLV_WIDTH-1:LGMEMLEN] };
334		generate if (SLV_WIDTH > AW)
335		begin : UNUSED_WIDE_ADDR
336			wire	unused_addr;
337			assign	unused_addr = &{ 1'b0,
338					next_src[SLV_WIDTH-1:AW],
339					next_dst[SLV_WIDTH-1:AW]
340					};
341		end if (SLV_WIDTH > LGDMALENGTH)
342		begin : UNUSED_LEN
343			wire	unused_len;
344			assign	unused_len = &{ 1'b0,
345					next_len[SLV_WIDTH-1:LGDMALENGTH]
346					};
347		end endgenerate
348		// Verilator lint_on  UNUSED
349		// Verilator coverage_on
350		// }}}
351	endmodule
352

