101	int	dma_memcpy(void *des, void *src, unsigned len) {
102		// {{{
103		if (_zipdma->d_ctrl & ZIPDMA_BUSY) {
104			printf("ERR: DMA is already busy\n");
105		} else {
106			_zipdma->d_src = src;
107			_zipdma->d_dst = des;
108			_zipdma->d_len = len;
109	
110			_zipdma->d_ctrl = DMACMD_MEMCPY;
111		}
112	
113		while(_zipdma->d_ctrl & ZIPDMA_BUSY) {
114			asm("NOOP");
115		} CLEAR_DCACHE;
116	
117		if (_zipdma->d_ctrl & ZIPDMA_ERR) {
118			printf("ERR: DMA transfer failed\n");
119			return 1;
120		}
121	
122		return 0;
123	}
