244	uint64_t lfsr_shift(uint64_t state) {
245		// {{{
246		uint64_t feedback = (state >> (DW-1)) ^ (state >> (DW-2));
247		uint64_t new_bit = feedback & 0x1;
248	
249		uint64_t result = ((state << 1) | new_bit);
250		return result;
251	}
